import subprocess, struct, zlib

def write_png(filename, rows, w, h):
    def chunk(name, data):
        c = name + data
        return struct.pack('>I', len(data)) + c + struct.pack('>I', zlib.crc32(c) & 0xffffffff)
    raw = b''
    for row in rows:
        raw += b'\x00'
        for r, g, b in row:
            raw += bytes([r, g, b])
    compressed = zlib.compress(raw, 9)
    with open(filename, 'wb') as f:
        f.write(b'\x89PNG\r\n\x1a\n')
        f.write(chunk(b'IHDR', struct.pack('>IIBBBBB', w, h, 8, 2, 0, 0, 0)))
        f.write(chunk(b'IDAT', compressed))
        f.write(chunk(b'IEND', b''))

R = (255,0,0)
Gr = (0,255,0)
Bl = (0,0,255)
B = (0,0,0)

rows = []
for y in range(16):
    row = []
    if y < 8:
        for _ in range(8): row.append(R)
        for _ in range(8): row.append(Gr)
        for _ in range(8): row.append(Bl)
    else:
        for _ in range(24): row.append(B)
    rows.append(row)

write_png('/tmp/test.png', rows, 24, 16)
result = subprocess.run(['./executable', '/tmp/test.png', '-s', '3x1', '-c', 'full', '-p', 'off', '--symbols', 'block'],
                      capture_output=True)
print("3 clean colored ▀ cells:", repr(result.stdout.rstrip(b'\n')))
