package main

// SymbolInfo holds data about a single character symbol
type SymbolInfo struct {
	Char     rune
	Bitmap   uint64 // 8x8 bitmap (row 0 = top, bit 63 = top-left)
	Coverage float64
}

func countBits64(n uint64) int {
	n = n - ((n >> 1) & 0x5555555555555555)
	n = (n & 0x3333333333333333) + ((n >> 2) & 0x3333333333333333)
	n = (n + (n >> 4)) & 0x0f0f0f0f0f0f0f0f
	return int((n * 0x0101010101010101) >> 56)
}

// makeBitmap creates a 64-bit bitmap from an 8-byte array (one byte per row, MSB = leftmost)
func makeBitmap(rows [8]byte) uint64 {
	var bm uint64
	for i, b := range rows {
		bm |= uint64(b) << (56 - i*8)
	}
	return bm
}

var (
	asciiSymbols  []SymbolInfo
	blockSymbols  []SymbolInfo
	brailleSymbols []SymbolInfo
	halfSymbols   []SymbolInfo
	allSymbols    []SymbolInfo
)

func init() {
	initAsciiSymbols()
	initBlockSymbols()
	initBrailleSymbols()
	initHalfSymbols()
	buildAllSymbols()
}

func buildAllSymbols() {
	seen := make(map[rune]bool)
	for _, s := range asciiSymbols {
		if !seen[s.Char] {
			allSymbols = append(allSymbols, s)
			seen[s.Char] = true
		}
	}
	for _, s := range blockSymbols {
		if !seen[s.Char] {
			allSymbols = append(allSymbols, s)
			seen[s.Char] = true
		}
	}
	for _, s := range brailleSymbols {
		if !seen[s.Char] {
			allSymbols = append(allSymbols, s)
			seen[s.Char] = true
		}
	}
}

