func initBrailleSymbols() {
	// Braille patterns U+2800-U+28FF
	// Braille dot layout for a 2x4 (cols x rows) grid
	// Dots 1-6: col0 rows 0-2, col1 rows 0-2
	// Dots 7-8: col0 row3, col1 row3
	// In unicode bit order: bit0=dot1, bit1=dot2, ..., bit7=dot8
	for b := 0; b < 256; b++ {
		var bitmap uint64
		// Map each braille dot to a 4x2 region in the 8x8 grid
		dotPos := [8][2]int{
			{0, 0}, // dot1: col0, row0
			{0, 1}, // dot2: col0, row1
			{0, 2}, // dot3: col0, row2
			{1, 0}, // dot4: col1, row0
			{1, 1}, // dot5: col1, row1
			{1, 2}, // dot6: col1, row2
			{0, 3}, // dot7: col0, row3
			{1, 3}, // dot8: col1, row3
		}
		for dot := 0; dot < 8; dot++ {
			if (b>>dot)&1 == 0 {
				continue
			}
			col := dotPos[dot][0]
			row := dotPos[dot][1]
			// Each dot covers 4 cols x 2 rows in the 8x8 grid
			for dc := 0; dc < 4; dc++ {
				for dr := 0; dr < 2; dr++ {
					pixCol := col*4 + dc
					pixRow := row*2 + dr
					bitPos := uint(pixRow*8 + pixCol)
					bitmap |= 1 << (63 - bitPos)
				}
			}
		}
		cov := float64(countBits64(bitmap)) / 64.0
		brailleSymbols = append(brailleSymbols, SymbolInfo{
			Char:     rune(0x2800 + b),
			Bitmap:   bitmap,
			Coverage: cov,
		})
	}
}

// getSymbolSet returns the symbols for a given set name
func getSymbolSet(name string) []SymbolInfo {
	name = strings.ToLower(name)
	parts := strings.FieldsFunc(name, func(r rune) bool {
		return r == '+' || r == '-'
	})
	ops := []byte{'+'}
	for i := 1; i < len(name); i++ {
		if name[i] == '+' || name[i] == '-' {
			ops = append(ops, name[i])
		}
	}

	var result []SymbolInfo
	seen := make(map[rune]bool)

	addSymbols := func(syms []SymbolInfo) {
		for _, s := range syms {
			if !seen[s.Char] {
				seen[s.Char] = true
				result = append(result, s)
			}
		}
	}
	removeSymbols := func(syms []SymbolInfo) {
		removeSet := make(map[rune]bool)
		for _, s := range syms {
			removeSet[s.Char] = true
		}
		var newResult []SymbolInfo
		for _, s := range result {
			if !removeSet[s.Char] {
				newResult = append(newResult, s)
			}
		}
		result = newResult
		for r := range removeSet {
			delete(seen, r)
		}
	}

	for i, part := range parts {
		op := byte('+')
		if i < len(ops) {
			op = ops[i]
		}
		var syms []SymbolInfo
		switch part {
		case "ascii":
			syms = asciiSymbols
		case "block":
			syms = blockSymbols
		case "braille":
			syms = brailleSymbols
		case "half":
			syms = halfSymbols
		case "space":
			syms = []SymbolInfo{{Char: ' ', Bitmap: 0, Coverage: 0}}
		case "all":
			syms = allSymbols
		case "none":
			syms = nil
		default:
			// Try specific sets
			switch part {
			case "alnum", "alpha", "digit":
				syms = asciiSymbols
			case "latin":
				syms = asciiSymbols
			case "wide":
				syms = blockSymbols
			case "narrow":
				syms = asciiSymbols
			case "border", "diagonal", "dot", "extra", "geometric", "inverted",
				"legacy", "quad", "sextant", "solid", "stipple", "technical",
				"ugly", "vhalf", "wedge", "hhalf", "imported", "ambiguous", "bad":
				// For unrecognized classes, use ascii as fallback
				syms = asciiSymbols
			default:
				syms = asciiSymbols
			}
		}
		if op == '+' {
			addSymbols(syms)
		} else {
			removeSymbols(syms)
		}
	}

	if len(result) == 0 {
		result = []SymbolInfo{{Char: ' ', Bitmap: 0, Coverage: 0}}
	}
	return result
}
