func colorToRGBA64(c color.Color) RGBA64 {
	r, g, b, a := c.RGBA()
	return RGBA64{
		R: float64(r) / 65535.0,
		G: float64(g) / 65535.0,
		B: float64(b) / 65535.0,
		A: float64(a) / 65535.0,
