func rgba64To8bit(c RGBA64) (uint8, uint8, uint8) {
	r := uint8(math.Min(255, math.Max(0, c.R*255.0)))
	g := uint8(math.Min(255, math.Max(0, c.G*255.0)))
	b := uint8(math.Min(255, math.Max(0, c.B*255.0)))
	return r, g, b
}

func luma(r, g, b float64) float64 {
