// cube6level converts 0-5 index to 256-color cube value
func cube6level(n int) uint8 {
	if n == 0 {
		return 0
	}
	return uint8(55 + 40*n)
}

// grayLevel returns the gray value for grayscale ramp entry n (232-255)
func grayLevel(n int) uint8 {
	return uint8(8 + 10*(n-232))
}

// Build the 256-color palette
var palette256 [256][3]uint8

func init() {
	// First 16: ANSI colors
	for i := 0; i < 16; i++ {
		palette256[i] = ansi16Colors[i]
	}
	// 16-231: 6x6x6 RGB cube
	for i := 16; i < 232; i++ {
		n := i - 16
		b := n % 6
		g := (n / 6) % 6
		r := (n / 36) % 6
		palette256[i] = [3]uint8{cube6level(r), cube6level(g), cube6level(b)}
	}
	// 232-255: grayscale ramp
	for i := 232; i < 256; i++ {
		v := grayLevel(i)
		palette256[i] = [3]uint8{v, v, v}
	}
}

// findNearest256 finds the closest 256-color palette entry
func findNearest256(r, g, b uint8) uint8 {
	best := 0
	bestDist := int64(math.MaxInt64)
	fr, fg, fb := int64(r), int64(g), int64(b)
	for i := 0; i < 256; i++ {
		pr, pg, pb := int64(palette256[i][0]), int64(palette256[i][1]), int64(palette256[i][2])
		dist := (fr-pr)*(fr-pr) + (fg-pg)*(fg-pg) + (fb-pb)*(fb-pb)
		if dist < bestDist {
			bestDist = dist
			best = i
		}
	}
	return uint8(best)
}

