		pr, pg, pb := int64(ansi16Colors[i][0]), int64(ansi16Colors[i][1]), int64(ansi16Colors[i][2])
		dist := (fr-pr)*(fr-pr) + (fg-pg)*(fg-pg) + (fb-pb)*(fb-pb)
