// findNearest2 finds the closest 2-color (black/white) entry
func findNearest2(r, g, b uint8) uint8 {
	gray := 0.2126*float64(r) + 0.7152*float64(g) + 0.0722*float64(b)
	if gray >= 127.5 {
		return 1
	}
	return 0
