func ansi16FGCode(idx uint8) int {
	if idx < 8 {
		return 30 + int(idx)
	}
	return 90 + int(idx-8)
}

func ansi16BGCode(idx uint8) int {
	if idx < 8 {
		return 40 + int(idx)
	}
	return 100 + int(idx-8)
}

