func ansi8BGCode(idx uint8) int {
	return 40 + int(idx)
}

// parseColor parses a color string (name or hex) into RGBA
func parseColor(s string) (color.RGBA, bool) {
	if s == "" {
		return color.RGBA{}, false
	}
	// Hex format #RRGGBB or #RGB
	if len(s) > 0 && s[0] == '#' {
		s = s[1:]
	}
	if len(s) == 6 {
		var r, g, b uint64
		if _, err := fmt.Sscanf(s[:2], "%x", &r); err == nil {
			if _, err := fmt.Sscanf(s[2:4], "%x", &g); err == nil {
				if _, err := fmt.Sscanf(s[4:6], "%x", &b); err == nil {
					return color.RGBA{uint8(r), uint8(g), uint8(b), 255}, true
				}
			}
		}
	}
	if len(s) == 3 {
		var r, g, b uint64
		if _, err := fmt.Sscanf(s[:1], "%x", &r); err == nil {
			if _, err := fmt.Sscanf(s[1:2], "%x", &g); err == nil {
				if _, err := fmt.Sscanf(s[2:3], "%x", &b); err == nil {
					return color.RGBA{uint8(r*17), uint8(g*17), uint8(b*17), 255}, true
				}
			}
		}
	}
	// Named colors
	named := map[string][3]uint8{
		"black":   {0, 0, 0},
		"white":   {255, 255, 255},
		"red":     {255, 0, 0},
		"green":   {0, 128, 0},
		"blue":    {0, 0, 255},
		"yellow":  {255, 255, 0},
		"cyan":    {0, 255, 255},
		"magenta": {255, 0, 255},
		"orange":  {255, 165, 0},
		"gray":    {128, 128, 128},
		"grey":    {128, 128, 128},
	}
	if c, ok := named[strings.ToLower(s)]; ok {
		return color.RGBA{c[0], c[1], c[2], 255}, true
	}
	return color.RGBA{}, false
}
