func loadGIF(data []byte) (*LoadedImage, error) {
	g, err := gif.DecodeAll(bytes.NewReader(data))
	if err != nil {
		return nil, err
	}
	if len(g.Image) == 0 {
		return nil, fmt.Errorf("empty GIF")
	}

	// Create composite frames
	var frames []ImageFrame
	width := g.Config.Width
	height := g.Config.Height
	if width == 0 || height == 0 {
		bounds := g.Image[0].Bounds()
		width = bounds.Max.X
		height = bounds.Max.Y
	}

	// Compose each frame
	canvas := image.NewRGBA(image.Rect(0, 0, width, height))
	// Fill with background
	bgColor := color.RGBA{0, 0, 0, 0}
	if g.BackgroundIndex < len(g.Image[0].Palette) {
		c := g.Image[0].Palette[g.BackgroundIndex]
		r, gg, b, a := c.RGBA()
		bgColor = color.RGBA{uint8(r >> 8), uint8(gg >> 8), uint8(b >> 8), uint8(a >> 8)}
	}
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			canvas.SetRGBA(x, y, bgColor)
		}
	}

	for i, frame := range g.Image {
		disposal := gif.DisposalNone
		if i < len(g.Disposal) {
			disposal = g.Disposal[i]
		}

		// Save canvas state before rendering if we'll need to restore
		var savedCanvas *image.RGBA
		if disposal == gif.DisposalBackground || disposal == gif.DisposalPrevious {
			savedCanvas = image.NewRGBA(canvas.Bounds())
			for y := 0; y < height; y++ {
				for x := 0; x < width; x++ {
					savedCanvas.SetRGBA(x, y, canvas.RGBAAt(x, y))
				}
			}
		}

		// Draw frame onto canvas
		bounds := frame.Bounds()
		for y := bounds.Min.Y; y < bounds.Max.Y; y++ {
			for x := bounds.Min.X; x < bounds.Max.X; x++ {
				src := frame.At(x, y)
				sr, sg, sb, sa := src.RGBA()
				if sa > 0 {
					canvas.SetRGBA(x, y, color.RGBA{uint8(sr >> 8), uint8(sg >> 8), uint8(sb >> 8), uint8(sa >> 8)})
				}
			}
		}

		// Take snapshot of composed canvas
		frameCopy := image.NewRGBA(image.Rect(0, 0, width, height))
		for y := 0; y < height; y++ {
			for x := 0; x < width; x++ {
				frameCopy.SetRGBA(x, y, canvas.RGBAAt(x, y))
			}
		}

		delayMs := 10 * 10 // default 100ms
		if i < len(g.Delay) {
			delayMs = g.Delay[i] * 10
		}
		if delayMs <= 0 {
			delayMs = 100
		}

		frames = append(frames, ImageFrame{Img: frameCopy, DelayMs: delayMs})

		// Handle disposal
		switch disposal {
		case gif.DisposalBackground:
			// Clear frame region with background
			for y := bounds.Min.Y; y < bounds.Max.Y; y++ {
				for x := bounds.Min.X; x < bounds.Max.X; x++ {
					canvas.SetRGBA(x, y, bgColor)
				}
			}
		case gif.DisposalPrevious:
			// Restore previous state
			if savedCanvas != nil {
				canvas = savedCanvas
			}
		}
	}

	isAnim := len(frames) > 1
	return &LoadedImage{
		Frames:  frames,
		Width:   width,
		Height:  height,
		IsAnim:  isAnim,
	}, nil
}

// loadQOI implements the QOI image format decoder
func loadQOI(data []byte) (*LoadedImage, error) {
	if len(data) < 14 {
		return nil, fmt.Errorf("QOI: too short")
	}
	width := int(binary.BigEndian.Uint32(data[4:8]))
	height := int(binary.BigEndian.Uint32(data[8:12]))
	channels := int(data[12])
	// colorspace := data[13]  // 0=sRGB, 1=linear

	if width == 0 || height == 0 || width > 65536 || height > 65536 {
		return nil, fmt.Errorf("QOI: invalid dimensions %dx%d", width, height)
	}

	img := image.NewRGBA(image.Rect(0, 0, width, height))

	var seen [64][4]uint8
	var prevR, prevG, prevB uint8 = 0, 0, 0
	var prevA uint8 = 255

	pos := 14
	pixIdx := 0
	total := width * height
	end := len(data) - 8 // 8-byte end marker

	for pixIdx < total && pos < end {
		b0 := data[pos]
		pos++

		var r, g, bl, a uint8

		if b0 == 0xFE { // QOI_OP_RGB
			if pos+3 > end {
				break
			}
			r, g, bl = data[pos], data[pos+1], data[pos+2]
			a = prevA
			pos += 3
		} else if b0 == 0xFF { // QOI_OP_RGBA
			if pos+4 > end {
				break
			}
			r, g, bl, a = data[pos], data[pos+1], data[pos+2], data[pos+3]
			pos += 4
		} else if b0>>6 == 0 { // QOI_OP_INDEX
			idx := b0 & 0x3F
			r, g, bl, a = seen[idx][0], seen[idx][1], seen[idx][2], seen[idx][3]
		} else if b0>>6 == 1 { // QOI_OP_DIFF
			dr := int8((b0>>4)&3) - 2
			dg := int8((b0>>2)&3) - 2
			db := int8(b0&3) - 2
			r = uint8(int(prevR) + int(dr))
			g = uint8(int(prevG) + int(dg))
			bl = uint8(int(prevB) + int(db))
			a = prevA
		} else if b0>>6 == 2 { // QOI_OP_LUMA
			if pos >= end {
				break
			}
			b1 := data[pos]
			pos++
			dg := int(b0&0x3F) - 32
			dr := int((b1>>4)&0xF) - 8 + dg
			db := int(b1&0xF) - 8 + dg
			r = uint8(int(prevR) + dr)
			g = uint8(int(prevG) + dg)
			bl = uint8(int(prevB) + db)
			a = prevA
		} else { // QOI_OP_RUN
			run := int(b0&0x3F) + 1
			r, g, bl, a = prevR, prevG, prevB, prevA
			// Fill run pixels
			for run > 0 && pixIdx < total {
				x := pixIdx % width
				y := pixIdx / width
				if channels == 4 {
					img.SetRGBA(x, y, color.RGBA{r, g, bl, a})
				} else {
					img.SetRGBA(x, y, color.RGBA{r, g, bl, 255})
				}
				pixIdx++
				run--
			}
			// Update seen table
			qoiIdx := (int(r)*3 + int(g)*5 + int(bl)*7 + int(a)*11) % 64
			seen[qoiIdx] = [4]uint8{r, g, bl, a}
			prevR, prevG, prevB, prevA = r, g, bl, a
			continue
		}

		// Store in seen table
		qoiIdx := (int(r)*3 + int(g)*5 + int(bl)*7 + int(a)*11) % 64
		seen[qoiIdx] = [4]uint8{r, g, bl, a}

		if pixIdx < total {
			x := pixIdx % width
			y := pixIdx / width
			if channels == 4 {
				img.SetRGBA(x, y, color.RGBA{r, g, bl, a})
			} else {
				img.SetRGBA(x, y, color.RGBA{r, g, bl, 255})
			}
			pixIdx++
		}

		prevR, prevG, prevB, prevA = r, g, bl, a
	}

	return &LoadedImage{
		Frames:  []ImageFrame{{Img: img, DelayMs: 0}},
		Width:   width,
		Height:  height,
		IsAnim:  false,
	}, nil
}

