// loadXWD provides minimal XWD (X Window Dump) support
func loadXWD(data []byte) (*LoadedImage, error) {
	if len(data) < 100 {
		return nil, fmt.Errorf("XWD: too short")
	}

	// XWD header is big-endian
	// headerSize = data[0:4]
	// fileVersion = data[4:8] (should be 7)
	fileVersion := int(binary.BigEndian.Uint32(data[4:8]))
	if fileVersion != 7 {
		return nil, fmt.Errorf("XWD: unsupported version %d", fileVersion)
	}

	// pixmapFormat = data[8:12]
	// pixmapDepth = data[12:16]
	pixmapDepth := int(binary.BigEndian.Uint32(data[12:16]))
	// pixmapWidth = data[16:20]
	pixmapWidth := int(binary.BigEndian.Uint32(data[16:20]))
	// pixmapHeight = data[20:24]
	pixmapHeight := int(binary.BigEndian.Uint32(data[20:24]))
	// xOffset = data[24:28]
	// byteOrder = data[28:32]
	byteOrder := int(binary.BigEndian.Uint32(data[28:32]))
	// bitmapUnit = data[32:36]
	// bitmapBitOrder = data[36:40]
	// bitmapPad = data[40:44]
	// bitsPerPixel = data[44:48]
	bitsPerPixel := int(binary.BigEndian.Uint32(data[44:48]))
	// bytesPerLine = data[48:52]
	bytesPerLine := int(binary.BigEndian.Uint32(data[48:52]))
	// visualClass = data[52:56]
	// redMask = data[56:60]
	redMask := uint32(binary.BigEndian.Uint32(data[56:60]))
	// greenMask = data[60:64]
	greenMask := uint32(binary.BigEndian.Uint32(data[60:64]))
	// blueMask = data[64:68]
	blueMask := uint32(binary.BigEndian.Uint32(data[64:68]))
	// bitsPerRgb = data[68:72]
	// colorMapEntries = data[72:76]
	colorMapEntries := int(binary.BigEndian.Uint32(data[72:76]))
	// nColors = data[76:80]
	// windowWidth = data[80:84]
	// windowHeight = data[84:88]
	// windowX = data[88:92]
	// windowY = data[92:96]
	// windowBorderWidth = data[96:100]

	headerSize := int(binary.BigEndian.Uint32(data[0:4]))

	// Color map follows the header
	colorMapOffset := headerSize
	colorMapSize := colorMapEntries * 12 // each entry is 12 bytes
	imageOffset := colorMapOffset + colorMapSize

	if imageOffset >= len(data) {
		return nil, fmt.Errorf("XWD: data too short")
	}

	img := image.NewRGBA(image.Rect(0, 0, pixmapWidth, pixmapHeight))
	imgData := data[imageOffset:]

	// Determine byte order
	isLittleEndian := (byteOrder == 0)

	for y := 0; y < pixmapHeight; y++ {
		rowOffset := y * bytesPerLine
		if rowOffset+bytesPerLine > len(imgData) {
			break
		}
		for x := 0; x < pixmapWidth; x++ {
			var pixel uint32
			byteOffset := rowOffset + x*(bitsPerPixel/8)
			if byteOffset+bitsPerPixel/8 > len(imgData) {
				break
			}
			switch bitsPerPixel {
			case 32:
				if isLittleEndian {
					pixel = binary.LittleEndian.Uint32(imgData[byteOffset:])
				} else {
					pixel = binary.BigEndian.Uint32(imgData[byteOffset:])
				}
			case 24:
				if isLittleEndian {
					pixel = uint32(imgData[byteOffset]) | uint32(imgData[byteOffset+1])<<8 | uint32(imgData[byteOffset+2])<<16
				} else {
					pixel = uint32(imgData[byteOffset])<<16 | uint32(imgData[byteOffset+1])<<8 | uint32(imgData[byteOffset+2])
				}
			case 16:
				if isLittleEndian {
					pixel = uint32(binary.LittleEndian.Uint16(imgData[byteOffset:]))
				} else {
					pixel = uint32(binary.BigEndian.Uint16(imgData[byteOffset:]))
				}
			}

			var r, g, b uint8
			if pixmapDepth > 8 {
				// Extract using masks
				r = uint8(extractBits(pixel, redMask))
				g = uint8(extractBits(pixel, greenMask))
				b = uint8(extractBits(pixel, blueMask))
			} else {
				// Indexed color
				r, g, b = 0, 0, 0
			}
			img.SetRGBA(x, y, color.RGBA{r, g, b, 255})
		}
	}

	return &LoadedImage{
		Frames:  []ImageFrame{{Img: img, DelayMs: 0}},
		Width:   pixmapWidth,
		Height:  pixmapHeight,
		IsAnim:  false,
	}, nil
}

func extractBits(pixel uint32, mask uint32) uint32 {
	if mask == 0 {
		return 0
	}
	// Find lowest set bit
	shift := 0
	for mask&(1<<uint(shift)) == 0 {
		shift++
	}
	// Find mask width
	bits := 0
	for (mask>>uint(shift))&(1<<uint(bits)) != 0 {
		bits++
	}
	val := (pixel & mask) >> uint(shift)
	// Scale to 8-bit
	if bits < 8 {
		val = val << uint(8-bits)
	} else if bits > 8 {
		val = val >> uint(bits-8)
	}
	return val
}
