		return nil, err
	}
	if len(g.Image) == 0 {
		return nil, fmt.Errorf("empty GIF")
	}

	// Create composite frames
	var frames []ImageFrame
	width := g.Config.Width
	height := g.Config.Height
	if width == 0 || height == 0 {
		bounds := g.Image[0].Bounds()
		width = bounds.Max.X
		height = bounds.Max.Y
	}

	// Compose each frame
	canvas := image.NewRGBA(image.Rect(0, 0, width, height))
	// Fill with background
	bgColor := color.RGBA{0, 0, 0, 0}
	if g.BackgroundIndex < len(g.Image[0].Palette) {
		c := g.Image[0].Palette[g.BackgroundIndex]
		r, gg, b, a := c.RGBA()
		bgColor = color.RGBA{uint8(r >> 8), uint8(gg >> 8), uint8(b >> 8), uint8(a >> 8)}
	}
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			canvas.SetRGBA(x, y, bgColor)
		}
	}

