		var savedCanvas *image.RGBA
		if disposal == gif.DisposalBackground || disposal == gif.DisposalPrevious {
			savedCanvas = image.NewRGBA(canvas.Bounds())
			for y := 0; y < height; y++ {
				for x := 0; x < width; x++ {
					savedCanvas.SetRGBA(x, y, canvas.RGBAAt(x, y))
				}
			}
		}

		// Draw frame onto canvas
		bounds := frame.Bounds()
		for y := bounds.Min.Y; y < bounds.Max.Y; y++ {
			for x := bounds.Min.X; x < bounds.Max.X; x++ {
				src := frame.At(x, y)
				sr, sg, sb, sa := src.RGBA()
				if sa > 0 {
					canvas.SetRGBA(x, y, color.RGBA{uint8(sr >> 8), uint8(sg >> 8), uint8(sb >> 8), uint8(sa >> 8)})
				}
			}
		}

		// Take snapshot of composed canvas
		frameCopy := image.NewRGBA(image.Rect(0, 0, width, height))
		for y := 0; y < height; y++ {
			for x := 0; x < width; x++ {
				frameCopy.SetRGBA(x, y, canvas.RGBAAt(x, y))
			}
		}

		delayMs := 10 * 10 // default 100ms
		if i < len(g.Delay) {
			delayMs = g.Delay[i] * 10
		}
		if delayMs <= 0 {
			delayMs = 100
		}

		frames = append(frames, ImageFrame{Img: frameCopy, DelayMs: delayMs})

		// Handle disposal
		switch disposal {
		case gif.DisposalBackground:
			// Clear frame region with background
			for y := bounds.Min.Y; y < bounds.Max.Y; y++ {
				for x := bounds.Min.X; x < bounds.Max.X; x++ {
					canvas.SetRGBA(x, y, bgColor)
				}
			}
		case gif.DisposalPrevious:
			// Restore previous state
			if savedCanvas != nil {
				canvas = savedCanvas
			}
		}
	}

	isAnim := len(frames) > 1
	return &LoadedImage{
		Frames:  frames,
		Width:   width,
		Height:  height,
		IsAnim:  isAnim,
	}, nil
}

