			py1 := y0 + (gy+1)*gridH/8

			if px1 <= px0 {
				px1 = px0 + 1
			}
			if py1 <= py0 {
				py1 = py0 + 1
			}

			var sumR, sumG, sumB, sumA float64
			count := 0
			for py := py0; py < py1; py++ {
				for px := px0; px < px1; px++ {
					c := img.At(px+bounds.Min.X, py+bounds.Min.Y)
					r, g, b, a := c.RGBA()
					fr := float64(r) / 65535.0
					fg := float64(g) / 65535.0
					fb := float64(b) / 65535.0
					fa := float64(a) / 65535.0
