		var err float64
		for gy := 0; gy < 8; gy++ {
			for gx := 0; gx < 8; gx++ {
				bit := uint(gy*8 + gx)
				isOn := (sym.Bitmap>>(63-bit))&1 == 1

				r := grid[gy][gx][0]
				g := grid[gy][gx][1]
				b := grid[gy][gx][2]

				var rendR, rendG, rendB float64
				if isOn {
					rendR, rendG, rendB = symFgR, symFgG, symFgB
				} else {
					if fgOnly {
						rendR, rendG, rendB = 0, 0, 0 // background not used
					} else {
						rendR, rendG, rendB = symBgR, symBgG, symBgB
					}
				}

				dr := r - rendR
				dg := g - rendG
				db := b - rendB
				err += dr*dr + dg*dg + db*db
			}
