}

func clamp255(v float64) float64 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return v
}

// RenderFrame renders a single image frame to a grid of cells
func RenderFrame(img image.Image, cols, rows int, symbols []SymbolInfo, cfg *Config) [][]Cell {
	result := make([][]Cell, rows)
	for row := range result {
		result[row] = make([]Cell, cols)
	}

	bgColor := color.RGBA{0, 0, 0, 255}
	if cfg.BgSet {
		bgColor = cfg.BgColor
	}

	threshold := cfg.Threshold
	if threshold <= 0 {
		threshold = 0.5
	}

	for row := 0; row < rows; row++ {
		for col := 0; col < cols; col++ {
			grid := sampleGrid(img, col, row, cols, rows, threshold)
			cell := findBestSymbol(grid, symbols, cfg.FgOnly, bgColor, cfg.BgSet, threshold)
			result[row][col] = cell
		}
	}

	return result
}

// calculateOutputSize calculates the output dimensions in characters
func calculateOutputSize(imgW, imgH, maxW, maxH int, fontRatio float64) (int, int) {
	if maxW <= 0 && maxH <= 0 {
		return 80, 24
	}
	if maxW <= 0 {
		maxW = 10000
	}
	if maxH <= 0 {
		maxH = 10000
	}

	// Natural height if we fill width
	naturalH := float64(maxW) * float64(imgH) / float64(imgW) * fontRatio
	if naturalH <= float64(maxH) {
		h := int(math.Ceil(naturalH))
		if h < 1 {
			h = 1
		}
		return maxW, h
	}

	// Fit by height
	naturalW := float64(maxH) * float64(imgW) / float64(imgH) / fontRatio
	w := int(math.Ceil(naturalW))
	if w < 1 {
		w = 1
	}
	if w > maxW {
		w = maxW
	}
	return w, maxH
}
