					fa := float64(a) / 65535.0
					// Pre-multiply alpha
					if fa > 0 {
						fr /= fa
						fg /= fa
						fb /= fa
					} else {
						fr, fg, fb = 0, 0, 0
					}
					sumR += fr * fa
					sumG += fg * fa
					sumB += fb * fa
					sumA += fa
					count++
				}
			}

			if count > 0 && sumA > 0 {
				grid[gy][gx][0] = sumR / sumA
				grid[gy][gx][1] = sumG / sumA
				grid[gy][gx][2] = sumB / sumA
				grid[gy][gx][3] = sumA / float64(count)
			} else {
				grid[gy][gx][3] = 0
			}
		}
	}

	return grid
}

// findBestSymbol finds the best character and colors for a given pixel grid
func findBestSymbol(grid [8][8][4]float64, symbols []SymbolInfo, fgOnly bool, bgColor color.RGBA, hasBgColor bool, threshold float64) Cell {
	// Compute average color for all pixels
	var sumR, sumG, sumB float64
	var nPix float64
	for gy := 0; gy < 8; gy++ {
		for gx := 0; gx < 8; gx++ {
			a := grid[gy][gx][3]
			if a >= threshold {
				sumR += grid[gy][gx][0]
				sumG += grid[gy][gx][1]
				sumB += grid[gy][gx][2]
				nPix++
			}
		}
	}

	if nPix == 0 {
		// All transparent
		return Cell{Char: ' ', CellColor: CellColor{
			BgR: bgColor.R, BgG: bgColor.G, BgB: bgColor.B, HasBg: false,
		}}
	}

	avgR := sumR / nPix
	avgG := sumG / nPix
	avgB := sumB / nPix

	bestError := math.MaxFloat64
	bestCell := Cell{Char: ' '}

	for _, sym := range symbols {
		var fgSumR, fgSumG, fgSumB float64
		var bgSumR, bgSumG, bgSumB float64
		fgCount := 0
		bgCount := 0

		for gy := 0; gy < 8; gy++ {
			for gx := 0; gx < 8; gx++ {
				bit := uint(gy*8 + gx)
				isOn := (sym.Bitmap>>(63-bit))&1 == 1

				r := grid[gy][gx][0]
				g := grid[gy][gx][1]
				b := grid[gy][gx][2]
				a := grid[gy][gx][3]

				// Blend with background if semi-transparent
				if a < 1.0 {
					bg := 0.0
					if hasBgColor {
						bg = 0 // use actual bg
					}
					r = r*a + bg*(1.0-a)
					g = g*a + bg*(1.0-a)
					b = b*a + bg*(1.0-a)
				}

				if isOn {
					fgSumR += r
					fgSumG += g
					fgSumB += b
					fgCount++
				} else {
					bgSumR += r
					bgSumG += g
					bgSumB += b
					bgCount++
				}
			}
		}

		// Compute optimal fg and bg colors
		var symFgR, symFgG, symFgB float64
		var symBgR, symBgG, symBgB float64

		if fgCount > 0 {
			symFgR = fgSumR / float64(fgCount)
			symFgG = fgSumG / float64(fgCount)
			symFgB = fgSumB / float64(fgCount)
		} else {
			symFgR, symFgG, symFgB = avgR, avgG, avgB
		}

		if bgCount > 0 {
			symBgR = bgSumR / float64(bgCount)
			symBgG = bgSumG / float64(bgCount)
			symBgB = bgSumB / float64(bgCount)
		} else {
			symBgR, symBgG, symBgB = avgR, avgG, avgB
		}

		// Compute error
		var err float64
		for gy := 0; gy < 8; gy++ {
			for gx := 0; gx < 8; gx++ {
				bit := uint(gy*8 + gx)
				isOn := (sym.Bitmap>>(63-bit))&1 == 1

				r := grid[gy][gx][0]
				g := grid[gy][gx][1]
				b := grid[gy][gx][2]

				var rendR, rendG, rendB float64
				if isOn {
					rendR, rendG, rendB = symFgR, symFgG, symFgB
				} else {
					if fgOnly {
						rendR, rendG, rendB = 0, 0, 0 // background not used
					} else {
						rendR, rendG, rendB = symBgR, symBgG, symBgB
					}
				}

				dr := r - rendR
				dg := g - rendG
				db := b - rendB
				err += dr*dr + dg*dg + db*db
			}
		}

		if err < bestError {
			bestError = err
			fgR := uint8(clamp255(symFgR * 255.0))
			fgG := uint8(clamp255(symFgG * 255.0))
			fgB := uint8(clamp255(symFgB * 255.0))
			bgR := uint8(clamp255(symBgR * 255.0))
			bgG := uint8(clamp255(symBgG * 255.0))
			bgB := uint8(clamp255(symBgB * 255.0))
			bestCell = Cell{
				Char: sym.Char,
				CellColor: CellColor{
					FgR: fgR, FgG: fgG, FgB: fgB, HasFg: true,
					BgR: bgR, BgG: bgG, BgB: bgB, HasBg: !fgOnly,
				},
			}
		}
	}

	return bestCell
}

func clamp255(v float64) float64 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return v
}

// RenderFrame renders a single image frame to a grid of cells
func RenderFrame(img image.Image, cols, rows int, symbols []SymbolInfo, cfg *Config) [][]Cell {
	result := make([][]Cell, rows)
	for row := range result {
		result[row] = make([]Cell, cols)
	}

	bgColor := color.RGBA{0, 0, 0, 255}
	if cfg.BgSet {
		bgColor = cfg.BgColor
	}

	threshold := cfg.Threshold
	if threshold <= 0 {
		threshold = 0.5
	}

	for row := 0; row < rows; row++ {
		for col := 0; col < cols; col++ {
			grid := sampleGrid(img, col, row, cols, rows, threshold)
			cell := findBestSymbol(grid, symbols, cfg.FgOnly, bgColor, cfg.BgSet, threshold)
			result[row][col] = cell
		}
	}

	return result
}

// calculateOutputSize calculates the output dimensions in characters
func calculateOutputSize(imgW, imgH, maxW, maxH int, fontRatio float64) (int, int) {
	if maxW <= 0 && maxH <= 0 {
		return 80, 24
	}
	if maxW <= 0 {
		maxW = 10000
	}
	if maxH <= 0 {
		maxH = 10000
	}

	// Natural height if we fill width
	naturalH := float64(maxW) * float64(imgH) / float64(imgW) * fontRatio
	if naturalH <= float64(maxH) {
		h := int(math.Ceil(naturalH))
		if h < 1 {
			h = 1
		}
		return maxW, h
	}

	// Fit by height
	naturalW := float64(maxH) * float64(imgW) / float64(imgH) / fontRatio
	w := int(math.Ceil(naturalW))
	if w < 1 {
		w = 1
	}
	if w > maxW {
		w = maxW
	}
	return w, maxH
}
