package main

import (
	"fmt"
	"io"
	"strings"
)

// OutputState tracks the current ANSI escape code state
type OutputState struct {
	FgR, FgG, FgB uint8
	BgR, BgG, BgB uint8
	FgSet         bool
	BgSet         bool
	Reverse       bool
	IsClean       bool // Just after ESC[0m
}

func newOutputState() *OutputState {
	return &OutputState{IsClean: true}
}

func (s *OutputState) reset(w io.Writer) {
	fmt.Fprintf(w, "\x1b[0m")
	s.FgR, s.FgG, s.FgB = 0, 0, 0
	s.BgR, s.BgG, s.BgB = 0, 0, 0
	s.FgSet = false
	s.BgSet = false
	s.Reverse = false
	s.IsClean = true
}

// OutputCells writes cells for a full color (24-bit) mode
func OutputCellsFull(w io.Writer, cells []Cell, state *OutputState, colorMode string) {
	for _, cell := range cells {
		outputCellFull(w, cell, state, colorMode)
	}
}

func outputCellFull(w io.Writer, cell Cell, state *OutputState, colorMode string) {
	char := cell.Char
	fgR, fgG, fgB := cell.FgR, cell.FgG, cell.FgB
	bgR, bgG, bgB := cell.BgR, cell.BgG, cell.BgB
	hasFg := cell.HasFg
	hasBg := cell.HasBg

	// Determine if this is a "uniform" cell (only one color matters)
	isUniform := (char == ' ') && (!hasFg || (fgR == bgR && fgG == bgG && fgB == bgB))
	if !hasBg {
		isUniform = true
	}

	if isUniform && state.IsClean {
		// Use reverse video mode for space char from clean state
		// The displayed color is the fg color (shown as bg via reverse)
		outputColorReverse(w, fgR, fgG, fgB, colorMode)
		writeChar(w, char)
		state.reset(w)
		return
	}

	// Direct mode: emit fg and bg as needed
	if state.IsClean {
		// From clean state, need to set both fg and bg
		outputColorDirect(w, fgR, fgG, fgB, bgR, bgG, bgB, hasFg, hasBg, colorMode)
		state.FgR, state.FgG, state.FgB = fgR, fgG, fgB
		state.BgR, state.BgG, state.BgB = bgR, bgG, bgB
		state.FgSet = hasFg
		state.BgSet = hasBg
		state.IsClean = false
	} else {
		// From set state, only emit changes
		fgChanged := hasFg && (fgR != state.FgR || fgG != state.FgG || fgB != state.FgB)
		bgChanged := hasBg && (bgR != state.BgR || bgG != state.BgG || bgB != state.BgB)

		if fgChanged && bgChanged {
			outputColorDirect(w, fgR, fgG, fgB, bgR, bgG, bgB, true, true, colorMode)
		} else if fgChanged {
			outputFgColor(w, fgR, fgG, fgB, colorMode)
		} else if bgChanged {
			outputBgColor(w, bgR, bgG, bgB, colorMode)
		}

		if hasFg {
			state.FgR, state.FgG, state.FgB = fgR, fgG, fgB
			state.FgSet = true
		}
		if hasBg {
			state.BgR, state.BgG, state.BgB = bgR, bgG, bgB
			state.BgSet = true
		}
	}

	writeChar(w, char)
}

func writeChar(w io.Writer, char rune) {
	fmt.Fprintf(w, "%c", char)
}

func outputColorReverse(w io.Writer, r, g, b uint8, colorMode string) {
	switch colorMode {
	case "full":
		fmt.Fprintf(w, "\x1b[7m\x1b[38;2;%d;%d;%dm", r, g, b)
	case "256":
		idx := findNearest256(r, g, b)
		fmt.Fprintf(w, "\x1b[7m\x1b[38;5;%dm", idx)
	case "16":
		idx := findNearest16(r, g, b)
		fmt.Fprintf(w, "\x1b[7m\x1b[%dm", ansi16FGCode(idx))
	case "16/8":
		idx := findNearest16(r, g, b)
		code := ansi8FGCode(idx & 7)
		fmt.Fprintf(w, "\x1b[7m\x1b[%dm", code)
	case "8":
		idx := findNearest8(r, g, b)
		fmt.Fprintf(w, "\x1b[7m\x1b[%dm", ansi8FGCode(idx))
	case "2":
		if findNearest2(r, g, b) == 1 {
			fmt.Fprintf(w, "\x1b[7m")
		}
		// else: just space, no color
	default:
		// none
	}
}

func outputColorDirect(w io.Writer, fgR, fgG, fgB, bgR, bgG, bgB uint8, hasFg, hasBg bool, colorMode string) {
	switch colorMode {
	case "full":
		if hasFg && hasBg {
			fmt.Fprintf(w, "\x1b[38;2;%d;%d;%d;48;2;%d;%d;%dm", fgR, fgG, fgB, bgR, bgG, bgB)
		} else if hasFg {
			fmt.Fprintf(w, "\x1b[38;2;%d;%d;%dm", fgR, fgG, fgB)
		} else if hasBg {
			fmt.Fprintf(w, "\x1b[48;2;%d;%d;%dm", bgR, bgG, bgB)
		}
	case "256":
		fgIdx := findNearest256(fgR, fgG, fgB)
		bgIdx := findNearest256(bgR, bgG, bgB)
		if hasFg && hasBg {
			fmt.Fprintf(w, "\x1b[38;5;%d;48;5;%dm", fgIdx, bgIdx)
		} else if hasFg {
			fmt.Fprintf(w, "\x1b[38;5;%dm", fgIdx)
		} else if hasBg {
			fmt.Fprintf(w, "\x1b[48;5;%dm", bgIdx)
		}
	case "16":
		fgIdx := findNearest16(fgR, fgG, fgB)
		bgIdx := findNearest16(bgR, bgG, bgB)
		if hasFg && hasBg {
			fmt.Fprintf(w, "\x1b[%d;%dm", ansi16FGCode(fgIdx), ansi16BGCode(bgIdx))
		} else if hasFg {
			fmt.Fprintf(w, "\x1b[%dm", ansi16FGCode(fgIdx))
		} else if hasBg {
			fmt.Fprintf(w, "\x1b[%dm", ansi16BGCode(bgIdx))
