func newOutputState() *OutputState {
	return &OutputState{IsClean: true}
}

func (s *OutputState) reset(w io.Writer) {
	fmt.Fprintf(w, "\x1b[0m")
	s.FgR, s.FgG, s.FgB = 0, 0, 0
	s.BgR, s.BgG, s.BgB = 0, 0, 0
	s.FgSet = false
	s.BgSet = false
	s.Reverse = false
	s.IsClean = true
}

