	for _, cell := range cells {
		outputCellFull(w, cell, state, colorMode)
	}
}

func outputCellFull(w io.Writer, cell Cell, state *OutputState, colorMode string) {
	char := cell.Char
	fgR, fgG, fgB := cell.FgR, cell.FgG, cell.FgB
	bgR, bgG, bgB := cell.BgR, cell.BgG, cell.BgB
	hasFg := cell.HasFg
	hasBg := cell.HasBg

	// Determine if this is a "uniform" cell (only one color matters)
	isUniform := (char == ' ') && (!hasFg || (fgR == bgR && fgG == bgG && fgB == bgB))
	if !hasBg {
		isUniform = true
	}

	if isUniform && state.IsClean {
		// Use reverse video mode for space char from clean state
		// The displayed color is the fg color (shown as bg via reverse)
		outputColorReverse(w, fgR, fgG, fgB, colorMode)
		writeChar(w, char)
		state.reset(w)
		return
	}

	// Direct mode: emit fg and bg as needed
	if state.IsClean {
		// From clean state, need to set both fg and bg
		outputColorDirect(w, fgR, fgG, fgB, bgR, bgG, bgB, hasFg, hasBg, colorMode)
		state.FgR, state.FgG, state.FgB = fgR, fgG, fgB
		state.BgR, state.BgG, state.BgB = bgR, bgG, bgB
		state.FgSet = hasFg
		state.BgSet = hasBg
		state.IsClean = false
	} else {
		// From set state, only emit changes
		fgChanged := hasFg && (fgR != state.FgR || fgG != state.FgG || fgB != state.FgB)
		bgChanged := hasBg && (bgR != state.BgR || bgG != state.BgG || bgB != state.BgB)

		if fgChanged && bgChanged {
			outputColorDirect(w, fgR, fgG, fgB, bgR, bgG, bgB, true, true, colorMode)
		} else if fgChanged {
			outputFgColor(w, fgR, fgG, fgB, colorMode)
		} else if bgChanged {
			outputBgColor(w, bgR, bgG, bgB, colorMode)
		}

		if hasFg {
			state.FgR, state.FgG, state.FgB = fgR, fgG, fgB
			state.FgSet = true
		}
		if hasBg {
			state.BgR, state.BgG, state.BgB = bgR, bgG, bgB
			state.BgSet = true
		}
	}

	writeChar(w, char)
