// colorDist2 returns squared Euclidean distance between two colors (float64)
func colorDist2(r1, g1, b1, r2, g2, b2 float64) float64 {
	dr := r1 - r2
	dg := g1 - g2
	db := b1 - b2
	return dr*dr + dg*dg + db*db
}

// The 16 ANSI colors used by chafa (approximate typical terminal values)
var ansi16Colors = [16][3]uint8{
	{0, 0, 0},       // 0: black
	{170, 0, 0},     // 1: dark red
	{0, 170, 0},     // 2: dark green
	{170, 170, 0},   // 3: dark yellow (olive)
	{0, 0, 170},     // 4: dark blue
	{170, 0, 170},   // 5: dark magenta
	{0, 170, 170},   // 6: dark cyan
	{170, 170, 170}, // 7: light gray
	{85, 85, 85},    // 8: dark gray
	{255, 85, 85},   // 9: bright red
	{85, 255, 85},   // 10: bright green
	{255, 255, 85},  // 11: bright yellow
	{85, 85, 255},   // 12: bright blue
	{255, 85, 255},  // 13: bright magenta
	{85, 255, 255},  // 14: bright cyan
	{255, 255, 255}, // 15: bright white
}

// The 8-color subset for -c 8 mode
var ansi8Colors = [8][3]uint8{
	{0, 0, 0},       // 0: black
	{170, 0, 0},     // 1: dark red
	{0, 170, 0},     // 2: dark green
	{170, 170, 0},   // 3: dark yellow
	{0, 0, 170},     // 4: dark blue
	{170, 0, 170},   // 5: dark magenta
	{0, 170, 170},   // 6: dark cyan
	{170, 170, 170}, // 7: light gray
}

// cube6level converts 0-5 index to 256-color cube value
func cube6level(n int) uint8 {
	if n == 0 {
		return 0
	}
	return uint8(55 + 40*n)
}

// grayLevel returns the gray value for grayscale ramp entry n (232-255)
func grayLevel(n int) uint8 {
	return uint8(8 + 10*(n-232))
}

// Build the 256-color palette
var palette256 [256][3]uint8

func init() {
	for i := 0; i < 16; i++ {
		palette256[i] = ansi16Colors[i]
	}
	for i := 16; i < 232; i++ {
		n := i - 16
		b := n % 6
		g := (n / 6) % 6
		r := (n / 36) % 6
		palette256[i] = [3]uint8{cube6level(r), cube6level(g), cube6level(b)}
	}
	for i := 232; i < 256; i++ {
		v := grayLevel(i)
		palette256[i] = [3]uint8{v, v, v}
	}
}

// findNearest256 finds the closest 256-color palette entry
func findNearest256(r, g, b uint8) uint8 {
	best := 0
	bestDist := int64(math.MaxInt32)
	fr, fg, fb := int64(r), int64(g), int64(b)
	for i := 0; i < 256; i++ {
		pr, pg, pb := int64(palette256[i][0]), int64(palette256[i][1]), int64(palette256[i][2])
		dist := (fr-pr)*(fr-pr) + (fg-pg)*(fg-pg) + (fb-pb)*(fb-pb)
		if dist < bestDist {
			bestDist = dist
			best = i
		}
	}
	return uint8(best)
}

// findNearest16 finds the closest 16-color ANSI entry
func findNearest16(r, g, b uint8) uint8 {
	best := 0
	bestDist := int64(math.MaxInt32)
	fr, fg, fb := int64(r), int64(g), int64(b)
	for i := 0; i < 16; i++ {
		pr, pg, pb := int64(ansi16Colors[i][0]), int64(ansi16Colors[i][1]), int64(ansi16Colors[i][2])
		dist := (fr-pr)*(fr-pr) + (fg-pg)*(fg-pg) + (fb-pb)*(fb-pb)
		if dist < bestDist {
			bestDist = dist
			best = i
		}
	}
	return uint8(best)
}

// findNearest8 finds the closest 8-color ANSI entry
func findNearest8(r, g, b uint8) uint8 {
	best := 0
	bestDist := int64(math.MaxInt32)
	fr, fg, fb := int64(r), int64(g), int64(b)
	for i := 0; i < 8; i++ {
		pr, pg, pb := int64(ansi8Colors[i][0]), int64(ansi8Colors[i][1]), int64(ansi8Colors[i][2])
		dist := (fr-pr)*(fr-pr) + (fg-pg)*(fg-pg) + (fb-pb)*(fb-pb)
		if dist < bestDist {
			bestDist = dist
			best = i
		}
	}
	return uint8(best)
}

// findNearest2 finds the closest 2-color (black/white) entry
func findNearest2(r, g, b uint8) uint8 {
	gray := 0.2126*float64(r) + 0.7152*float64(g) + 0.0722*float64(b)
	if gray >= 127.5 {
		return 1
	}
	return 0
}

func ansi16FGCode(idx uint8) int {
	if idx < 8 {
		return 30 + int(idx)
	}
	return 90 + int(idx-8)
}

func ansi16BGCode(idx uint8) int {
	if idx < 8 {
		return 40 + int(idx)
	}
	return 100 + int(idx-8)
}

func ansi8FGCode(idx uint8) int {
	return 30 + int(idx)
}

func ansi8BGCode(idx uint8) int {
	return 40 + int(idx)
}

// parseColor parses a color string into RGBA
func parseColor(s string) (color.RGBA, bool) {
	if s == "" {
		return color.RGBA{}, false
	}
	str := s
	if len(str) > 0 && str[0] == '#' {
		str = str[1:]
	}
	if len(str) == 6 {
		var ri, gi, bi uint64
		if _, err := fmt.Sscanf(str[0:2], "%x", &ri); err == nil {
			if _, err := fmt.Sscanf(str[2:4], "%x", &gi); err == nil {
				if _, err := fmt.Sscanf(str[4:6], "%x", &bi); err == nil {
					return color.RGBA{uint8(ri), uint8(gi), uint8(bi), 255}, true
				}
			}
		}
	}
	if len(str) == 3 {
		var ri, gi, bi uint64
		if _, err := fmt.Sscanf(str[0:1], "%x", &ri); err == nil {
			if _, err := fmt.Sscanf(str[1:2], "%x", &gi); err == nil {
				if _, err := fmt.Sscanf(str[2:3], "%x", &bi); err == nil {
					return color.RGBA{uint8(ri * 17), uint8(gi * 17), uint8(bi * 17), 255}, true
				}
			}
		}
	}
	named := map[string][3]uint8{
		"black":   {0, 0, 0},
		"white":   {255, 255, 255},
		"red":     {255, 0, 0},
		"green":   {0, 128, 0},
		"blue":    {0, 0, 255},
		"yellow":  {255, 255, 0},
		"cyan":    {0, 255, 255},
		"magenta": {255, 0, 255},
		"orange":  {255, 165, 0},
		"gray":    {128, 128, 128},
		"grey":    {128, 128, 128},
	}
	if c, ok := named[strings.ToLower(s)]; ok {
		return color.RGBA{c[0], c[1], c[2], 255}, true
	}
	return color.RGBA{}, false
}

// suppress unused
var _ = colorDist2
