func parseBoolArg(s string) (bool, error) {
	switch strings.ToLower(s) {
	case "on", "yes", "true", "1":
		return true, nil
	case "off", "no", "false", "0":
		return false, nil
	}
	return false, fmt.Errorf("invalid bool: %s", s)
}

func parseSizeArg(s string) (int, int, error) {
	lower := strings.ToLower(s)
	parts := strings.SplitN(lower, "x", 2)
	if len(parts) == 1 {
		n, err := strconv.Atoi(s)
		if err != nil {
			return 0, 0, fmt.Errorf("invalid size: %s", s)
		}
		return n, 0, nil
	}
	var w, h int
	var err error
	if parts[0] != "" {
		w, err = strconv.Atoi(parts[0])
		if err != nil {
			return 0, 0, fmt.Errorf("invalid size: %s", s)
		}
	}
	if parts[1] != "" {
		h, err = strconv.Atoi(parts[1])
		if err != nil {
			return 0, 0, fmt.Errorf("invalid size: %s", s)
		}
	}
	return w, h, nil
}

func parseFontRatio(s string) (float64, error) {
	if strings.Contains(s, "/") {
		parts := strings.SplitN(s, "/", 2)
		n, err1 := strconv.ParseFloat(parts[0], 64)
		d, err2 := strconv.ParseFloat(parts[1], 64)
		if err1 != nil || err2 != nil || d == 0 {
			return 0, fmt.Errorf("invalid font-ratio: %s", s)
		}
		return n / d, nil
	}
	v, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return 0, fmt.Errorf("invalid font-ratio: %s", s)
	}
	return v, nil
}

// getArgValue extracts the value for an argument
// If arg contains '=', returns everything after '='
// Otherwise returns the next arg
func getArgValue(arg string, nextArgs []string) (string, int) {
	if idx := strings.Index(arg, "="); idx >= 0 {
		return arg[idx+1:], 0
	}
	if len(nextArgs) > 0 {
		return nextArgs[0], 1
	}
	return "", 0
}

// needsValue checks if an option typically takes a value
func parseArgs(args []string) (*Config, []string, error) {
	cfg := defaultConfig()
	var files []string
	progName := "chafa"
	if len(args) > 0 {
		progName = filepath.Base(args[0])
		args = args[1:]
	}
	_ = progName

	i := 0
	for i < len(args) {
		arg := args[i]
		nextArgs := args[i+1:]

		if arg == "--" {
			files = append(files, args[i+1:]...)
			break
		}

		if !strings.HasPrefix(arg, "-") {
			files = append(files, arg)
			i++
			continue
		}

		consumed := 0

		switch {
		case arg == "-h" || arg == "--help":
			printHelp(filepath.Base(os.Args[0]))
			os.Exit(0)
		case arg == "--version":
			printVersion()
			os.Exit(0)
		case arg == "-v" || arg == "--verbose":
			cfg.Verbose = true
		case arg == "--clear":
			cfg.Clear = true
		case arg == "--stretch":
			cfg.Stretch = true
			cfg.ScaleMax = true
		case arg == "--fit-width":
			cfg.FitWidth = true
		case arg == "--invert":
			cfg.Invert = true
		case arg == "--fg-only":
			cfg.FgOnly = true
		case arg == "--watch":
			cfg.Watch = true
		case arg == "-g":
			// grid auto - ignore
		case arg == "-l":
			// label on - ignore
		case arg == "-s" || strings.HasPrefix(arg, "-s=") ||
			arg == "--size" || strings.HasPrefix(arg, "--size="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			w, h, e := parseSizeArg(val)
			if e != nil {
				return nil, nil, e
			}
			sz := [2]int{w, h}
			cfg.Size = &sz
			consumed = extra
		case arg == "-c" || strings.HasPrefix(arg, "-c=") ||
			arg == "--colors" || strings.HasPrefix(arg, "--colors="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			cfg.Colors = val
			consumed = extra
		case arg == "-f" || strings.HasPrefix(arg, "-f=") ||
			arg == "--format" || strings.HasPrefix(arg, "--format="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			cfg.Format = val
			consumed = extra
		case arg == "-d" || strings.HasPrefix(arg, "-d=") ||
			arg == "--duration" || strings.HasPrefix(arg, "--duration="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			d, e := strconv.ParseFloat(val, 64)
			if e != nil {
				return nil, nil, fmt.Errorf("invalid duration: %s", val)
			}
			cfg.Duration = d
			consumed = extra
		case arg == "--symbols" || strings.HasPrefix(arg, "--symbols="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			cfg.Symbols = val
			consumed = extra
		case arg == "--fill" || strings.HasPrefix(arg, "--fill="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			cfg.Fill = val
			consumed = extra
		case arg == "--font-ratio" || strings.HasPrefix(arg, "--font-ratio="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			fr, e := parseFontRatio(val)
			if e != nil {
				return nil, nil, e
			}
			cfg.FontRatio = fr
			consumed = extra
		case arg == "--bg" || strings.HasPrefix(arg, "--bg="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			c, ok := parseColor(val)
			if ok {
				cfg.BgColor = c
				cfg.BgSet = true
			}
			consumed = extra
		case arg == "--fg" || strings.HasPrefix(arg, "--fg="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			c, ok := parseColor(val)
			if ok {
				cfg.FgColor = c
				cfg.FgSet = true
			}
			consumed = extra
		case arg == "-p" || strings.HasPrefix(arg, "-p=") ||
			arg == "--preprocess" || strings.HasPrefix(arg, "--preprocess="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			b, e := parseBoolArg(val)
			if e != nil {
				return nil, nil, e
			}
			if b {
				cfg.Preprocess = 1
			} else {
				cfg.Preprocess = 0
			}
			consumed = extra
		case arg == "-t" || strings.HasPrefix(arg, "-t=") ||
			arg == "--threshold" || strings.HasPrefix(arg, "--threshold="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			t, e := strconv.ParseFloat(val, 64)
			if e != nil {
				return nil, nil, fmt.Errorf("invalid threshold: %s", val)
			}
			cfg.Threshold = t
			consumed = extra
		case arg == "-O" || strings.HasPrefix(arg, "-O=") ||
			arg == "--optimize" || strings.HasPrefix(arg, "--optimize="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			n, e := strconv.Atoi(val)
			if e != nil {
				return nil, nil, fmt.Errorf("invalid optimize: %s", val)
			}
			cfg.Optimize = n
			consumed = extra
		case arg == "-w" || strings.HasPrefix(arg, "-w=") ||
			arg == "--work" || strings.HasPrefix(arg, "--work="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			n, e := strconv.Atoi(val)
			if e != nil {
				return nil, nil, fmt.Errorf("invalid work: %s", val)
			}
			cfg.Work = n
			consumed = extra
		case arg == "--scale" || strings.HasPrefix(arg, "--scale="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			if strings.ToLower(val) == "max" {
				cfg.ScaleMax = true
			} else {
				s, e := strconv.ParseFloat(val, 64)
				if e != nil {
					return nil, nil, fmt.Errorf("invalid scale: %s", val)
				}
				cfg.Scale = s
			}
			consumed = extra
		case arg == "--animate" || strings.HasPrefix(arg, "--animate="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			b, e := parseBoolArg(val)
			if e != nil {
				return nil, nil, e
			}
			cfg.Animate = b
			consumed = extra
		case arg == "--speed" || strings.HasPrefix(arg, "--speed="):
			_, extra := getArgValue(arg, nextArgs)
			consumed = extra
		case arg == "--files0" || strings.HasPrefix(arg, "--files0="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			cfg.Files0 = val
			consumed = extra
		case arg == "--files" || strings.HasPrefix(arg, "--files="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			cfg.Files = val
			consumed = extra
		case arg == "--view-size" || strings.HasPrefix(arg, "--view-size="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			w, h, e := parseSizeArg(val)
			if e != nil {
				return nil, nil, e
			}
			sz := [2]int{w, h}
			cfg.ViewSize = &sz
			consumed = extra
		case arg == "--probe-mode" || strings.HasPrefix(arg, "--probe-mode="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			cfg.ProbeMode = val
			consumed = extra
		case arg == "--probe" || strings.HasPrefix(arg, "--probe="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			cfg.Probe = val
			consumed = extra
		case arg == "--glyph-file" || strings.HasPrefix(arg, "--glyph-file="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			cfg.GlyphFile = val
			consumed = extra
		case arg == "--margin-bottom" || strings.HasPrefix(arg, "--margin-bottom="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			n, e := strconv.Atoi(val)
			if e != nil {
				return nil, nil, fmt.Errorf("invalid margin-bottom: %s", val)
			}
			cfg.MarginBottom = n
			consumed = extra
		case arg == "--margin-right" || strings.HasPrefix(arg, "--margin-right="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			n, e := strconv.Atoi(val)
			if e != nil {
				return nil, nil, fmt.Errorf("invalid margin-right: %s", val)
			}
			cfg.MarginRight = n
			consumed = extra
		case arg == "--threads" || strings.HasPrefix(arg, "--threads="):
			val, extra := getArgValue(arg, nextArgs)
			if val == "" {
				return nil, nil, fmt.Errorf("missing value for %s", arg)
			}
			n, e := strconv.Atoi(val)
			if e != nil {
				return nil, nil, fmt.Errorf("invalid threads: %s", val)
			}
			cfg.Threads = n
			consumed = extra
		// Options that accept a value but we ignore
		case arg == "--align" || strings.HasPrefix(arg, "--align="),
			arg == "--exact-size" || strings.HasPrefix(arg, "--exact-size="),
			arg == "--relative" || strings.HasPrefix(arg, "--relative="),
			arg == "--passthrough" || strings.HasPrefix(arg, "--passthrough="),
			arg == "--polite" || strings.HasPrefix(arg, "--polite="),
			arg == "--color-extractor" || strings.HasPrefix(arg, "--color-extractor="),
			arg == "--color-space" || strings.HasPrefix(arg, "--color-space="),
			arg == "--dither" || strings.HasPrefix(arg, "--dither="),
			arg == "--dither-grain" || strings.HasPrefix(arg, "--dither-grain="),
			arg == "--dither-intensity" || strings.HasPrefix(arg, "--dither-intensity="),
			arg == "--grid" || strings.HasPrefix(arg, "--grid="),
			arg == "--label" || strings.HasPrefix(arg, "--label="),
			arg == "--link" || strings.HasPrefix(arg, "--link="):
			_, extra := getArgValue(arg, nextArgs)
			consumed = extra
		default:
			return nil, nil, fmt.Errorf("Unknown option %s", arg)
		}

		i += 1 + consumed
	}

	return cfg, files, nil
}

func readFileList(path string, nul bool) ([]string, error) {
	var f *os.File
	var err error
	if path == "-" {
		f = os.Stdin
	} else {
		f, err = os.Open(path)
		if err != nil {
			return nil, err
		}
		defer f.Close()
	}

	data, err := io.ReadAll(f)
	if err != nil {
		return nil, err
	}

	var sep string
	if nul {
		sep = "\x00"
	} else {
		sep = "\n"
	}

	parts := strings.Split(string(data), sep)
	var result []string
	for _, p := range parts {
		p = strings.TrimRight(p, "\r")
		if p != "" {
			result = append(result, p)
		}
	}
	return result, nil
}

func processFile(path string, cfg *Config, colorMode string, symbols []SymbolInfo, w io.Writer) int {
	loaded, err := LoadImage(path)
	if err != nil {
		progName := filepath.Base(os.Args[0])
		if os.IsNotExist(err) {
			fmt.Fprintf(os.Stderr, "%s: Failed to open '%s': No such file or directory\n", progName, path)
		} else {
			errStr := err.Error()
			if strings.Contains(errStr, "Could not cache") || strings.Contains(errStr, "cache input") {
				fmt.Fprintf(os.Stderr, "%s: Failed to open '%s': Could not cache input stream\n", progName, path)
			} else {
				fmt.Fprintf(os.Stderr, "%s: Failed to open '%s': %v\n", progName, path, err)
			}
		}
		return 2
	}

	// Determine output size
	termW, termH := getTermSize()

	viewW, viewH := termW, termH
	if cfg.ViewSize != nil {
		if cfg.ViewSize[0] > 0 {
			viewW = cfg.ViewSize[0]
		}
		if cfg.ViewSize[1] > 0 {
			viewH = cfg.ViewSize[1]
		}
	}

	// Apply margins
	viewW -= cfg.MarginRight
	viewH -= cfg.MarginBottom
	if viewW < 1 {
		viewW = 1
	}
	if viewH < 1 {
		viewH = 1
	}

	maxW, maxH := viewW, viewH
	if cfg.Size != nil {
		if cfg.Size[0] > 0 {
			maxW = cfg.Size[0]
		} else if cfg.Size[1] > 0 {
			maxW = 10000
		}
		if cfg.Size[1] > 0 {
			maxH = cfg.Size[1]
		} else if cfg.Size[0] > 0 {
			maxH = 10000
		}
	}

	imgW := loaded.Width
	imgH := loaded.Height

	var outW, outH int
	if cfg.Stretch {
		outW = maxW
		outH = maxH
	} else {
		outW, outH = calculateOutputSize(imgW, imgH, maxW, maxH, cfg.FontRatio)
	}

	if outW <= 0 {
		outW = 1
	}
	if outH <= 0 {
		outH = 1
	}
	if outW > maxW {
		outW = maxW
	}
	if outH > maxH {
		outH = maxH
	}

	// Clear screen if requested
	if cfg.Clear {
		fmt.Fprintf(w, "\x1b[2J\x1b[H")
	}

	frames := loaded.Frames

	if !cfg.Animate || len(frames) == 1 {
		cells := RenderFrame(frames[0].Img, outW, outH, symbols, cfg)
		WriteOutput(w, cells, colorMode)
		return 0
	}

	// Animation
	duration := cfg.Duration
	if duration < 0 {
		if loaded.IsAnim {
			duration = math.MaxFloat64 / 2
		} else {
			duration = 0
		}
	}

	startTime := time.Now()
	frameIdx := 0
	isFirst := true

	bw, isBuf := w.(*bufio.Writer)
	if !isBuf {
		bw = bufio.NewWriter(w)
	}

	for {
		frame := frames[frameIdx%len(frames)]
		cells := RenderFrame(frame.Img, outW, outH, symbols, cfg)

		if !isFirst {
			fmt.Fprintf(bw, "\x1b[%dA", outH)
		}

		WriteOutput(bw, cells, colorMode)
		bw.Flush()
		isFirst = false

		delayMs := frame.DelayMs
		if delayMs <= 0 {
			delayMs = 100
		}

		elapsed := time.Since(startTime).Seconds()
		if duration < math.MaxFloat64/2 && elapsed >= duration && frameIdx >= len(frames)-1 {
			break
		}

		time.Sleep(time.Duration(delayMs) * time.Millisecond)
		frameIdx++

		if duration <= 0 && frameIdx >= len(frames) {
			break
		}
		if duration < math.MaxFloat64/2 && elapsed >= duration {
			break
		}
	}

	return 0
}

func main() {
	cfg, files, err := parseArgs(os.Args)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s: %s\n", filepath.Base(os.Args[0]), err)
		os.Exit(2)
	}

	// Add files from --files option
	if cfg.Files != "" {
		extraFiles, err := readFileList(cfg.Files, false)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s: Could not read file list: %v\n",
				filepath.Base(os.Args[0]), err)
			os.Exit(2)
		}
		files = append(extraFiles, files...)
	}

	// Add files from --files0 option
	if cfg.Files0 != "" {
		extraFiles, err := readFileList(cfg.Files0, true)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s: Could not read file list: %v\n",
				filepath.Base(os.Args[0]), err)
			os.Exit(2)
		}
		files = append(extraFiles, files...)
	}

	// If no files specified, try stdin
	if len(files) == 0 {
		files = []string{"-"}
	}

	// Determine color mode
	colorMode := resolveColorMode(cfg.Colors)

	// Get symbols
	symbols := getSymbolSet(cfg.Symbols)

	// Process files
	w := bufio.NewWriter(os.Stdout)
	exitCode := 0
	for _, path := range files {
		code := processFile(path, cfg, colorMode, symbols, w)
		if code != 0 {
			exitCode = code
		}
	}
	w.Flush()

	os.Exit(exitCode)
}
