// sampleRegion samples the image region for a character cell into an 8x8 grid
func sampleRegion(img image.Image, cellX, cellY, totalCellsW, totalCellsH int) [8][8][4]float64 {
	bounds := img.Bounds()
	imgW := bounds.Dx()
	imgH := bounds.Dy()

	// Calculate pixel region for this cell
	x0 := cellX * imgW / totalCellsW
	x1 := (cellX + 1) * imgW / totalCellsW
	y0 := cellY * imgH / totalCellsH
	y1 := (cellY + 1) * imgH / totalCellsH

	if x1 <= x0 {
		x1 = x0 + 1
	}
	if y1 <= y0 {
		y1 = y0 + 1
	}

	var grid [8][8][4]float64
	gridW := x1 - x0
	gridH := y1 - y0

	for gy := 0; gy < 8; gy++ {
		for gx := 0; gx < 8; gx++ {
			px0 := x0 + gx*gridW/8
			px1 := x0 + (gx+1)*gridW/8
			py0 := y0 + gy*gridH/8
			py1 := y0 + (gy+1)*gridH/8

			if px1 <= px0 {
				px1 = px0 + 1
			}
			if py1 <= py0 {
				py1 = py0 + 1
			}

			var sumR, sumG, sumB, sumA float64
			count := 0
			for py := py0; py < py1; py++ {
				for px := px0; px < px1; px++ {
					c := img.At(px+bounds.Min.X, py+bounds.Min.Y)
					r, g, b, a := c.RGBA()
					fr := float64(r) / 65535.0
					fg := float64(g) / 65535.0
					fb := float64(b) / 65535.0
					fa := float64(a) / 65535.0
					if fa > 0 {
						sumR += fr
						sumG += fg
						sumB += fb
					}
					sumA += fa
					count++
				}
			}

			if count > 0 && sumA > 0 {
				grid[gy][gx][0] = sumR / float64(count)
				grid[gy][gx][1] = sumG / float64(count)
				grid[gy][gx][2] = sumB / float64(count)
				grid[gy][gx][3] = sumA / float64(count)
			}
		}
	}

	return grid
}

// computeCellColors computes the optimal fg and bg colors for a character and pixel grid
// Returns (fgR, fgG, fgB, bgR, bgG, bgB) as float64 [0,1]
func computeCellColors(grid [8][8][4]float64, sym SymbolInfo) (float64, float64, float64, float64, float64, float64) {
	var fgSumR, fgSumG, fgSumB float64
	var bgSumR, bgSumG, bgSumB float64
	fgCount := 0
	bgCount := 0

	for gy := 0; gy < 8; gy++ {
		for gx := 0; gx < 8; gx++ {
			bit := uint(gy*8 + gx)
			isOn := (sym.Bitmap>>(63-bit))&1 == 1

			r := grid[gy][gx][0]
			g := grid[gy][gx][1]
			b := grid[gy][gx][2]

			if isOn {
				fgSumR += r
				fgSumG += g
				fgSumB += b
				fgCount++
			} else {
				bgSumR += r
				bgSumG += g
				bgSumB += b
				bgCount++
			}
		}
	}

	var fgR, fgG, fgB float64
	var bgR, bgG, bgB float64

	// Compute averages
	if fgCount > 0 {
		fgR = fgSumR / float64(fgCount)
		fgG = fgSumG / float64(fgCount)
		fgB = fgSumB / float64(fgCount)
	}
	if bgCount > 0 {
		bgR = bgSumR / float64(bgCount)
		bgG = bgSumG / float64(bgCount)
		bgB = bgSumB / float64(bgCount)
	}
	// If no on-pixels: fg = avg of all
	if fgCount == 0 {
		fgR, fgG, fgB = bgR, bgG, bgB
	}
	// If no off-pixels: bg = avg of all
	if bgCount == 0 {
		bgR, bgG, bgB = fgR, fgG, fgB
	}

	return fgR, fgG, fgB, bgR, bgG, bgB
}

// computeError computes the rendering error for a character
func computeError(grid [8][8][4]float64, sym SymbolInfo, fgR, fgG, fgB, bgR, bgG, bgB float64) float64 {
