package main

import (
	"fmt"
	"io"
	"strings"
)

// TermState tracks the current terminal color state
type TermState struct {
	FgR, FgG, FgB   uint8
	BgR, BgG, BgB   uint8
	FgKnown         bool // do we know the current fg?
	BgKnown         bool // do we know the current bg?
	AtStart         bool // are we at "clean/reset" state?
}

func newTermState() *TermState {
	return &TermState{AtStart: true}
}

// resetState marks the state as reset/clean
func (s *TermState) resetState(w io.Writer) {
	fmt.Fprintf(w, "\x1b[0m")
	s.FgR, s.FgG, s.FgB = 0, 0, 0
	s.BgR, s.BgG, s.BgB = 0, 0, 0
	s.FgKnown = false
	s.BgKnown = false
	s.AtStart = true
}

// setFgColor emits fg color escape code for a given mode
func setFgColor(w io.Writer, r, g, b uint8, colorMode string) {
	switch colorMode {
	case "full":
		fmt.Fprintf(w, "\x1b[38;2;%d;%d;%dm", r, g, b)
	case "256":
		fmt.Fprintf(w, "\x1b[38;5;%dm", findNearest256(r, g, b))
	case "16":
		fmt.Fprintf(w, "\x1b[%dm", ansi16FGCode(findNearest16(r, g, b)))
	case "16/8":
		fmt.Fprintf(w, "\x1b[%dm", ansi8FGCode(findNearest16(r, g, b)&7))
	case "8":
		fmt.Fprintf(w, "\x1b[%dm", ansi8FGCode(findNearest8(r, g, b)))
	}
}

// setBgColor emits bg color escape code for a given mode
func setBgColor(w io.Writer, r, g, b uint8, colorMode string) {
	switch colorMode {
	case "full":
		fmt.Fprintf(w, "\x1b[48;2;%d;%d;%dm", r, g, b)
	case "256":
		fmt.Fprintf(w, "\x1b[48;5;%dm", findNearest256(r, g, b))
	case "16":
		fmt.Fprintf(w, "\x1b[%dm", ansi16BGCode(findNearest16(r, g, b)))
	case "16/8":
		fmt.Fprintf(w, "\x1b[%dm", ansi8BGCode(findNearest16(r, g, b)&7))
	case "8":
		fmt.Fprintf(w, "\x1b[%dm", ansi8BGCode(findNearest8(r, g, b)))
	}
}

// setFgBgColor emits both fg and bg color escape code for a given mode
func setFgBgColor(w io.Writer, fr, fg_, fb, br, bg_, bb uint8, colorMode string) {
	switch colorMode {
	case "full":
		fmt.Fprintf(w, "\x1b[38;2;%d;%d;%d;48;2;%d;%d;%dm", fr, fg_, fb, br, bg_, bb)
	case "256":
		fmt.Fprintf(w, "\x1b[38;5;%d;48;5;%dm", findNearest256(fr, fg_, fb), findNearest256(br, bg_, bb))
	case "16":
		fmt.Fprintf(w, "\x1b[%d;%dm", ansi16FGCode(findNearest16(fr, fg_, fb)), ansi16BGCode(findNearest16(br, bg_, bb)))
	case "16/8":
		fmt.Fprintf(w, "\x1b[%d;%dm", ansi8FGCode(findNearest16(fr, fg_, fb)&7), ansi8BGCode(findNearest16(br, bg_, bb)&7))
	case "8":
		fmt.Fprintf(w, "\x1b[%d;%dm", ansi8FGCode(findNearest8(fr, fg_, fb)), ansi8BGCode(findNearest8(br, bg_, bb)))
	}
}

// colorEquiv checks if two colors are the same in the given color mode
func colorEquiv(r1, g1, b1, r2, g2, b2 uint8, colorMode string) bool {
	switch colorMode {
	case "full":
		return r1 == r2 && g1 == g2 && b1 == b2
	case "256":
		return findNearest256(r1, g1, b1) == findNearest256(r2, g2, b2)
	case "16":
		return findNearest16(r1, g1, b1) == findNearest16(r2, g2, b2)
	case "16/8":
		return findNearest16(r1, g1, b1)&7 == findNearest16(r2, g2, b2)&7
	case "8":
		return findNearest8(r1, g1, b1) == findNearest8(r2, g2, b2)
	}
	return false
}

// WriteRow outputs a single row of cells to the writer
func WriteRow(w io.Writer, cells []Cell, state *TermState, colorMode string) {
	if colorMode == "none" {
		for _, cell := range cells {
			fmt.Fprintf(w, "%c", cell.Char)
		}
		fmt.Fprintln(w)
		return
	}

	// For color modes, track state and emit minimal escape codes
	for _, cell := range cells {
		writeCellColor(w, cell, state, colorMode)
	}

	// End of row: reset if not already at start
	if !state.AtStart {
		state.resetState(w)
	}
	fmt.Fprintln(w)
}

// writeCellColor writes a single colored cell
func writeCellColor(w io.Writer, cell Cell, state *TermState, colorMode string) {
	fgR, fgG, fgB := cell.FgR, cell.FgG, cell.FgB
	bgR, bgG, bgB := cell.BgR, cell.BgG, cell.BgB
	char := cell.Char

	if colorMode == "2" {
		// Binary color mode: use reverse video for "white" cells
		isWhite := findNearest2(bgR, bgG, bgB) == 1
		if isWhite {
			if state.AtStart {
				fmt.Fprintf(w, "\x1b[7m")
				state.AtStart = false
				state.BgKnown = true
			} else {
				// Already in colored state, just emit reverse if needed
			}
			fmt.Fprintf(w, "%c", char)
		} else {
			// Black cell: just output char with no extra codes
			if !state.AtStart {
				// Already in state, no need for codes
			}
			fmt.Fprintf(w, "%c", char)
		}
		return
	}

	// For uniform cells (fg==bg): use simplified encoding
	if cell.FgEqBg || char == ' ' {
		displayColor := bgR
		displayColorG := bgG
		displayColorB := bgB
		if char == ' ' && cell.FgEqBg {
			displayColor = fgR
			displayColorG = fgG
			displayColorB = fgB
		}

		if state.AtStart {
			// After reset: use reverse video + fg color
			fmt.Fprintf(w, "\x1b[7m")
			setFgColor(w, displayColor, displayColorG, displayColorB, colorMode)
			state.FgR, state.FgG, state.FgB = displayColor, displayColorG, displayColorB
			state.FgKnown = true
			state.BgKnown = false
			state.AtStart = false
			fmt.Fprintf(w, "%c", char)
			state.resetState(w)
		} else {
			// Not at start: set fg=0, bg=displayColor
			// Update fg to 0 if needed
			fgNeedsChange := !state.FgKnown || state.FgR != 0 || state.FgG != 0 || state.FgB != 0
			bgNeedsChange := !state.BgKnown || !colorEquiv(state.BgR, state.BgG, state.BgB, displayColor, displayColorG, displayColorB, colorMode)

			if fgNeedsChange && bgNeedsChange {
				setFgBgColor(w, 0, 0, 0, displayColor, displayColorG, displayColorB, colorMode)
