			}
			state.BgR, state.BgG, state.BgB = displayColor, displayColorG, displayColorB
			state.BgKnown = true
			fmt.Fprintf(w, "%c", char)
		}
		return
	}

	// Non-uniform cell: needs explicit fg and bg
	if state.AtStart {
		// After reset: emit both fg and bg together
		setFgBgColor(w, fgR, fgG, fgB, bgR, bgG, bgB, colorMode)
		state.FgR, state.FgG, state.FgB = fgR, fgG, fgB
		state.BgR, state.BgG, state.BgB = bgR, bgG, bgB
		state.FgKnown = true
		state.BgKnown = true
		state.AtStart = false
	} else {
		// Not at start: only emit changes
		fgChanged := !state.FgKnown || !colorEquiv(state.FgR, state.FgG, state.FgB, fgR, fgG, fgB, colorMode)
		bgChanged := !state.BgKnown || !colorEquiv(state.BgR, state.BgG, state.BgB, bgR, bgG, bgB, colorMode)

		if fgChanged && bgChanged {
			setFgBgColor(w, fgR, fgG, fgB, bgR, bgG, bgB, colorMode)
		} else if fgChanged {
			setFgColor(w, fgR, fgG, fgB, colorMode)
		} else if bgChanged {
			setBgColor(w, bgR, bgG, bgB, colorMode)
		}
		state.FgR, state.FgG, state.FgB = fgR, fgG, fgB
		state.BgR, state.BgG, state.BgB = bgR, bgG, bgB
		state.FgKnown = true
		state.BgKnown = true
	}

	fmt.Fprintf(w, "%c", char)
}

// WriteOutput outputs all cells to the writer
func WriteOutput(w io.Writer, rows [][]Cell, colorMode string) {
	if colorMode == "none" {
		for _, row := range rows {
			for _, cell := range row {
				fmt.Fprintf(w, "%c", cell.Char)
			}
			fmt.Fprintln(w)
		}
