func WriteOutput(w io.Writer, rows [][]Cell, colorMode string) {
	if colorMode == "none" {
		for _, row := range rows {
			for _, cell := range row {
				fmt.Fprintf(w, "%c", cell.Char)
			}
			fmt.Fprintln(w)
		}
		return
	}

	state := newTermState()
	// Initial reset
	state.emitReset(w)
	state.RowStart = true

	for _, row := range rows {
		WriteRow(w, row, state, colorMode)
	}
}

// resolveColorMode determines the actual color mode to use
func resolveColorMode(mode string) string {
	mode = strings.ToLower(mode)
	switch mode {
	case "none", "":
		return "none"
	case "2":
		return "2"
	case "8":
		return "8"
	case "16/8":
		return "16/8"
	case "16":
		return "16"
	case "240":
		return "256"
	case "256":
		return "256"
	case "full", "true", "24bit", "rgb":
		return "full"
	case "auto", "best":
		return "full"
	default:
		return "full"
	}
}
