		fmt.Fprintf(w, "\x1b[38;5;%d;48;5;%dm", findNearest256(fr, fg_, fb), findNearest256(br, bg_, bb))
	case "16":
		fmt.Fprintf(w, "\x1b[%d;%dm", ansi16FGCode(findNearest16(fr, fg_, fb)), ansi16BGCode(findNearest16(br, bg_, bb)))
	case "16/8":
		fmt.Fprintf(w, "\x1b[%d;%dm", ansi8FGCode(findNearest16(fr, fg_, fb)&7), ansi8BGCode(findNearest16(br, bg_, bb)&7))
	case "8":
		fmt.Fprintf(w, "\x1b[%d;%dm", ansi8FGCode(findNearest8(fr, fg_, fb)), ansi8BGCode(findNearest8(br, bg_, bb)))
	}
}

// writeCell writes a single cell with appropriate escape codes
func writeCell(w io.Writer, cell Cell, state *TermState, mode string) {
	char := cell.Char
	isUniform := cell.FgEqBg || char == ' ' || (!cell.HasBg)

	bgColor := [3]uint8{cell.BgR, cell.BgG, cell.BgB}
	fgColor := [3]uint8{cell.FgR, cell.FgG, cell.FgB}

	if char == ' ' && cell.FgEqBg {
		// Space with same fg and bg: the "display color" is the bg
		bgColor = [3]uint8{cell.BgR, cell.BgG, cell.BgB}
		fgColor = bgColor
	} else if char == ' ' {
		// Space without fg: display color is bg
		bgColor = [3]uint8{cell.BgR, cell.BgG, cell.BgB}
		fgColor = bgColor
	}

	if mode == "none" {
		fmt.Fprintf(w, "%c", char)
		return
	}

	if mode == "2" {
		isWhite := findNearest2(bgColor[0], bgColor[1], bgColor[2]) == 1
		if state.RowStart && isWhite {
			fmt.Fprintf(w, "\x1b[7m ")
			state.emitReset(w)
		} else if isWhite {
			fmt.Fprintf(w, "\x1b[7m ")
			state.emitReset(w)
		} else {
			fmt.Fprintf(w, "%c", char)
		}
		state.RowStart = false
		return
	}

	if isUniform {
		// Uniform cell (or space with color)
		dispR, dispG, dispB := bgColor[0], bgColor[1], bgColor[2]

		if state.RowStart {
			// First cell in row: use reverse video
			fmt.Fprintf(w, "\x1b[7m")
			setFg(w, dispR, dispG, dispB, mode)
			state.FgR, state.FgG, state.FgB = dispR, dispG, dispB
			state.FgKnown = true
			state.BgKnown = false
			state.IsClean = false
			state.RowStart = false
			fmt.Fprintf(w, "%c", char)
			state.emitReset(w)
		} else {
			// Not first in row: use direct bg mode
			// After previous cell's ESC[0m, IsClean=true, FgKnown=false
			// We need bg=dispColor, fg doesn't matter (space char)
			// Set fg=0, bg=dispColor explicitly
			fgNeedsChange := state.FgKnown && (state.FgR != 0 || state.FgG != 0 || state.FgB != 0)
			bgNeedsChange := !state.BgKnown || !colorEquiv(state.BgR, state.BgG, state.BgB, dispR, dispG, dispB, mode)

			if !state.FgKnown || fgNeedsChange {
				if bgNeedsChange {
					setFgBg(w, 0, 0, 0, dispR, dispG, dispB, mode)
					state.FgR, state.FgG, state.FgB = 0, 0, 0
					state.FgKnown = true
				} else {
					setFg(w, 0, 0, 0, mode)
					state.FgR, state.FgG, state.FgB = 0, 0, 0
					state.FgKnown = true
				}
			} else if bgNeedsChange {
				setBg(w, dispR, dispG, dispB, mode)
			}
			state.BgR, state.BgG, state.BgB = dispR, dispG, dispB
			state.BgKnown = true
			state.IsClean = false
			fmt.Fprintf(w, "%c", char)
		}
		return
	}

	// Non-uniform cell: explicit fg and bg
	fr, fg_, fb := fgColor[0], fgColor[1], fgColor[2]
	br, bg_, bb := bgColor[0], bgColor[1], bgColor[2]

	if state.IsClean || state.RowStart {
		// From clean state: emit both
		setFgBg(w, fr, fg_, fb, br, bg_, bb, mode)
		state.FgR, state.FgG, state.FgB = fr, fg_, fb
		state.BgR, state.BgG, state.BgB = br, bg_, bb
		state.FgKnown = true
		state.BgKnown = true
		state.IsClean = false
		state.RowStart = false
	} else {
		// Continuing from previous: only emit changes
		fgChanged := !state.FgKnown || !colorEquiv(state.FgR, state.FgG, state.FgB, fr, fg_, fb, mode)
		bgChanged := !state.BgKnown || !colorEquiv(state.BgR, state.BgG, state.BgB, br, bg_, bb, mode)

		if fgChanged && bgChanged {
			setFgBg(w, fr, fg_, fb, br, bg_, bb, mode)
		} else if fgChanged {
			setFg(w, fr, fg_, fb, mode)
		} else if bgChanged {
			setBg(w, br, bg_, bb, mode)
		}
		state.FgR, state.FgG, state.FgB = fr, fg_, fb
		state.BgR, state.BgG, state.BgB = br, bg_, bb
		state.FgKnown = true
		state.BgKnown = true
	}

	fmt.Fprintf(w, "%c", char)
}

// WriteRow outputs a single row of cells
func WriteRow(w io.Writer, cells []Cell, state *TermState, mode string) {
	if mode == "none" {
		for _, cell := range cells {
			fmt.Fprintf(w, "%c", cell.Char)
		}
		fmt.Fprintln(w)
		return
	}

	// Mark start of row
	state.RowStart = true

	for _, cell := range cells {
		writeCell(w, cell, state, mode)
	}

	// End of row
	if !state.IsClean {
		state.emitReset(w)
	}
	fmt.Fprintln(w)
}

// WriteOutput outputs all cells to the writer
func WriteOutput(w io.Writer, rows [][]Cell, colorMode string) {
	if colorMode == "none" {
		for _, row := range rows {
			for _, cell := range row {
				fmt.Fprintf(w, "%c", cell.Char)
			}
			fmt.Fprintln(w)
		}
		return
	}

	state := newTermState()
	// Initial reset
	state.emitReset(w)
	state.RowStart = true

	for _, row := range rows {
		WriteRow(w, row, state, colorMode)
	}
}

// resolveColorMode determines the actual color mode to use
func resolveColorMode(mode string) string {
	mode = strings.ToLower(mode)
	switch mode {
	case "none", "":
		return "none"
	case "2":
		return "2"
	case "8":
		return "8"
	case "16/8":
		return "16/8"
	case "16":
		return "16"
	case "240":
		return "256"
	case "256":
		return "256"
	case "full", "true", "24bit", "rgb":
		return "full"
	case "auto", "best":
		return "full"
	default:
		return "full"
	}
}
