// sampleRegion samples the image region for a character cell into an 8x8 grid
func sampleRegion(img image.Image, cellX, cellY, totalCellsW, totalCellsH int) [8][8][4]float64 {
	bounds := img.Bounds()
	imgW := bounds.Dx()
	imgH := bounds.Dy()

	x0 := cellX * imgW / totalCellsW
	x1 := (cellX + 1) * imgW / totalCellsW
	y0 := cellY * imgH / totalCellsH
	y1 := (cellY + 1) * imgH / totalCellsH

	if x1 <= x0 {
		x1 = x0 + 1
	}
	if y1 <= y0 {
		y1 = y0 + 1
	}

	var grid [8][8][4]float64
	gridW := x1 - x0
	gridH := y1 - y0

	for gy := 0; gy < 8; gy++ {
		for gx := 0; gx < 8; gx++ {
			px0 := x0 + gx*gridW/8
			px1 := x0 + (gx+1)*gridW/8
			py0 := y0 + gy*gridH/8
			py1 := y0 + (gy+1)*gridH/8

			if px1 <= px0 {
				px1 = px0 + 1
			}
			if py1 <= py0 {
				py1 = py0 + 1
			}

			var sumR, sumG, sumB, sumA float64
			count := 0
			for py := py0; py < py1; py++ {
				for px := px0; px < px1; px++ {
					c := img.At(px+bounds.Min.X, py+bounds.Min.Y)
					r, g, b, a := c.RGBA()
					fr := float64(r) / 65535.0
					fg := float64(g) / 65535.0
					fb := float64(b) / 65535.0
					fa := float64(a) / 65535.0
					if fa > 0 {
						sumR += fr
						sumG += fg
						sumB += fb
					}
					sumA += fa
					count++
				}
			}

			if count > 0 && sumA > 0 {
				grid[gy][gx][0] = sumR / float64(count)
				grid[gy][gx][1] = sumG / float64(count)
				grid[gy][gx][2] = sumB / float64(count)
				grid[gy][gx][3] = sumA / float64(count)
			}
		}
	}

	return grid
}

// computeCellAvg computes the average color of the grid
func computeCellAvg(grid [8][8][4]float64) (float64, float64, float64, float64) {
	var sumR, sumG, sumB, sumA float64
	for gy := 0; gy < 8; gy++ {
		for gx := 0; gx < 8; gx++ {
			sumR += grid[gy][gx][0]
			sumG += grid[gy][gx][1]
			sumB += grid[gy][gx][2]
			sumA += grid[gy][gx][3]
		}
	}
	return sumR / 64, sumG / 64, sumB / 64, sumA / 64
}

// computeCellColors computes optimal fg/bg colors for a character
func computeCellColors(grid [8][8][4]float64, sym SymbolInfo) (float64, float64, float64, float64, float64, float64) {
	var fgSumR, fgSumG, fgSumB float64
	var bgSumR, bgSumG, bgSumB float64
	fgCount := 0
	bgCount := 0

	for gy := 0; gy < 8; gy++ {
		for gx := 0; gx < 8; gx++ {
			bit := uint(gy*8 + gx)
			isOn := (sym.Bitmap>>(63-bit))&1 == 1

			r := grid[gy][gx][0]
			g := grid[gy][gx][1]
			b := grid[gy][gx][2]

			if isOn {
				fgSumR += r
				fgSumG += g
				fgSumB += b
				fgCount++
			} else {
				bgSumR += r
				bgSumG += g
				bgSumB += b
				bgCount++
			}
		}
	}

	var fgR, fgG, fgB float64
	var bgR, bgG, bgB float64

	if fgCount > 0 {
		fgR = fgSumR / float64(fgCount)
		fgG = fgSumG / float64(fgCount)
		fgB = fgSumB / float64(fgCount)
	}
	if bgCount > 0 {
		bgR = bgSumR / float64(bgCount)
		bgG = bgSumG / float64(bgCount)
		bgB = bgSumB / float64(bgCount)
	}
	if fgCount == 0 {
		fgR, fgG, fgB = bgR, bgG, bgB
	}
	if bgCount == 0 {
		bgR, bgG, bgB = fgR, fgG, fgB
	}

	return fgR, fgG, fgB, bgR, bgG, bgB
}

// computeError computes the rendering error
func computeError(grid [8][8][4]float64, sym SymbolInfo, fgR, fgG, fgB, bgR, bgG, bgB float64) float64 {
	var err float64
	for gy := 0; gy < 8; gy++ {
		for gx := 0; gx < 8; gx++ {
			bit := uint(gy*8 + gx)
			isOn := (sym.Bitmap>>(63-bit))&1 == 1

			r := grid[gy][gx][0]
			g := grid[gy][gx][1]
			b := grid[gy][gx][2]

			var rendR, rendG, rendB float64
			if isOn {
				rendR, rendG, rendB = fgR, fgG, fgB
			} else {
				rendR, rendG, rendB = bgR, bgG, bgB
			}

			dr := r - rendR
			dg := g - rendG
			db := b - rendB
			err += dr*dr + dg*dg + db*db
		}
	}
	return err
}

// isNearlyUniform checks if all pixels are close to the same value
func isNearlyUniform(grid [8][8][4]float64) bool {
	r0, g0, b0 := grid[0][0][0], grid[0][0][1], grid[0][0][2]
	const eps = 0.01
	for gy := 0; gy < 8; gy++ {
		for gx := 0; gx < 8; gx++ {
			if math.Abs(grid[gy][gx][0]-r0) > eps ||
				math.Abs(grid[gy][gx][1]-g0) > eps ||
				math.Abs(grid[gy][gx][2]-b0) > eps {
				return false
			}
		}
	}
	return true
}

func clamp255(v float64) float64 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return v
}

// symCoverageThreshold returns the "threshold brightness" for a character
// Characters win when brightness >= this threshold AND they have highest threshold <= brightness
// For -c none mode tiebreaking
func symCoverageThreshold(sym SymbolInfo) float64 {
	// Use bitmap coverage as approximation
	// Scale it so that typical thresholds emerge
	// space=0, typical "light" char ~0.34, typical "dark" char ~0.50
	cov := sym.Coverage
	if cov <= 0 {
		return 0
	}
	// Apply a slight non-linear transformation to better match observed thresholds
	// Empirically: threshold ≈ sqrt(coverage) * some_factor... but complex
	// Simple: just use coverage directly, and sort symbols so coverage ordering
	// gives the right selection
	return cov
}

// findBestCellNone finds best char for -c none mode
func findBestCellNone(grid [8][8][4]float64, symbols []SymbolInfo) Cell {
	// Compute average brightness
	avgR, avgG, avgB, _ := computeCellAvg(grid)
	avgBright := 0.2126*avgR + 0.7152*avgG + 0.0722*avgB

	// For uniform cells: use coverage threshold selection
	if isNearlyUniform(grid) {
		// Find char with highest coverage <= brightness
		bestChar := ' '
		var bestCov float64 = -1
		for _, sym := range symbols {
			cov := symCoverageThreshold(sym)
			if cov <= avgBright && cov > bestCov {
				bestCov = cov
				bestChar = sym.Char
			}
		}
		if bestChar == 0 {
			bestChar = ' '
		}
		return Cell{Char: bestChar}
	}

	// Non-uniform: standard error minimization with optimal fg/bg
	// Use fg=1, bg=0 as fixed colors for character matching
	bestErr := math.MaxFloat64
	bestCell := Cell{Char: ' '}

	for _, sym := range symbols {
		// With fixed fg=white(1.0), bg=black(0.0):
		err := computeError(grid, sym, 1.0, 1.0, 1.0, 0.0, 0.0, 0.0)

		if err < bestErr-1e-10 {
			bestErr = err
			bestCell = Cell{Char: sym.Char}
		} else if math.Abs(err-bestErr) < 1e-10 {
			// Tie: prefer higher coverage (last one wins)
			bestCell = Cell{Char: sym.Char}
		}
	}

	return bestCell
}

// findBestCell finds best char/colors for color modes
func findBestCell(grid [8][8][4]float64, symbols []SymbolInfo, fgOnly bool, _ color.RGBA, _ bool) Cell {
	// Check if uniform
	if isNearlyUniform(grid) {
		// For uniform cells: use SPACE with fg=bg=color
		r, g, b, _ := computeCellAvg(grid)
		r8 := uint8(clamp255(r * 255.0))
		g8 := uint8(clamp255(g * 255.0))
		b8 := uint8(clamp255(b * 255.0))
		return Cell{
			Char:   ' ',
			FgR:    r8, FgG: g8, FgB: b8,
			BgR:    r8, BgG: g8, BgB: b8,
			HasFg:  true, HasBg: true,
			FgEqBg: true,
		}
	}

	// Non-uniform: minimize error with optimal fg/bg
	bestErr := math.MaxFloat64
	bestCell := Cell{Char: ' '}

	for _, sym := range symbols {
		fgR, fgG, fgB, bgR, bgG, bgB := computeCellColors(grid, sym)
		err := computeError(grid, sym, fgR, fgG, fgB, bgR, bgG, bgB)

		if err < bestErr {
			bestErr = err
			r8 := uint8(clamp255(fgR * 255.0))
			g8 := uint8(clamp255(fgG * 255.0))
			b8 := uint8(clamp255(fgB * 255.0))
			br8 := uint8(clamp255(bgR * 255.0))
			bg8 := uint8(clamp255(bgG * 255.0))
			bb8 := uint8(clamp255(bgB * 255.0))
			fgEq := (r8 == br8 && g8 == bg8 && b8 == bb8)
			bestCell = Cell{
				Char:   sym.Char,
				FgR:    r8, FgG: g8, FgB: b8,
				BgR:    br8, BgG: bg8, BgB: bb8,
				HasFg:  true, HasBg: !fgOnly,
				FgEqBg: fgEq,
			}
		}
	}

	return bestCell
}

// RenderFrame renders a single image frame to a grid of cells
func RenderFrame(img image.Image, cols, rows int, symbols []SymbolInfo, cfg *Config) [][]Cell {
	result := make([][]Cell, rows)
	for row := range result {
		result[row] = make([]Cell, cols)
	}

	colorMode := resolveColorMode(cfg.Colors)
	bgColor := color.RGBA{0, 0, 0, 255}
	if cfg.BgSet {
		bgColor = cfg.BgColor
	}

	for row := 0; row < rows; row++ {
		for col := 0; col < cols; col++ {
			grid := sampleRegion(img, col, row, cols, rows)

			var cell Cell
			if colorMode == "none" {
				cell = findBestCellNone(grid, symbols)
			} else {
				cell = findBestCell(grid, symbols, cfg.FgOnly, bgColor, cfg.BgSet)
			}
			result[row][col] = cell
		}
	}

	return result
}

// calculateOutputSize calculates the output dimensions in characters
func calculateOutputSize(imgW, imgH, maxW, maxH int, fontRatio float64) (int, int) {
	if maxW <= 0 && maxH <= 0 {
		return 80, 24
	}
	if maxW <= 0 {
		maxW = 10000
	}
	if maxH <= 0 {
		maxH = 10000
	}

	naturalH := float64(maxW) * float64(imgH) / float64(imgW) * fontRatio
	if naturalH <= float64(maxH) {
		h := int(math.Ceil(naturalH))
		if h < 1 {
			h = 1
		}
		return maxW, h
	}

	naturalW := float64(maxH) * float64(imgW) / float64(imgH) / fontRatio
	w := int(math.Ceil(naturalW))
	if w < 1 {
		w = 1
	}
	if w > maxW {
		w = maxW
	}
	return w, maxH
}
