// calculateOutputSize calculates the output dimensions in characters
func calculateOutputSize(imgW, imgH, maxW, maxH int, fontRatio float64) (int, int) {
	if maxW <= 0 && maxH <= 0 {
		return 80, 24
	}
	if maxW <= 0 {
		maxW = 10000
	}
	if maxH <= 0 {
		maxH = 10000
	}

	naturalH := float64(maxW) * float64(imgH) / float64(imgW) * fontRatio
	if naturalH <= float64(maxH) {
		h := int(math.Ceil(naturalH))
		if h < 1 {
			h = 1
		}
		return maxW, h
	}

	naturalW := float64(maxH) * float64(imgW) / float64(imgH) / fontRatio
	w := int(math.Ceil(naturalW))
	if w < 1 {
		w = 1
	}
	if w > maxW {
		w = maxW
	}
	return w, maxH
}
