func uniformCharForBrightness(brightness float64, symbols []SymbolInfo) rune {
	// Fixed thresholds based on empirical observation:
	// space=0-86/255, medium=87/255-128/255, dense=129/255-255/255
	const thresh1 = 87.0 / 255.0
	const thresh2 = 129.0 / 255.0

	// Find the character set we're working with to determine appropriate chars
	// Try to find a space-like char (coverage ~0), a medium char, and a dense char
	var spaceChar, medChar, denseChar rune = ' ', ':', '@'

	for _, sym := range symbols {
		if sym.Char == ' ' {
			spaceChar = ' '
		}
	}

	// Find char with medium coverage (for ~0.34 threshold)
	// and char with high coverage (for ~0.51 threshold)
	var medCov, denseCov float64
	for _, sym := range symbols {
		if sym.Char == ' ' {
			continue
		}
		cov := sym.Coverage
		if cov > 0 && cov <= 0.50 {
			if cov > medCov {
				medCov = cov
				medChar = sym.Char
			}
		} else if cov > 0.50 {
			if cov > denseCov {
				denseCov = cov
				denseChar = sym.Char
			}
		}
	}

	if denseCov == 0 && medCov > 0 {
		// Only 2 levels: space and one other
		if brightness >= thresh1 - 1e-10 {
			return medChar
		}
		return spaceChar
	}

	if brightness >= thresh2 - 1e-10 {
		return denseChar
	}
	if brightness >= thresh1 - 1e-10 {
		return medChar
	}
	return spaceChar
}"""

new_func = """// uniformCharForBrightness returns the best character for a uniform cell
// in -c none mode using sorted coverage values
func uniformCharForBrightness(brightness float64, symbols []SymbolInfo) rune {
	// Fixed thresholds based on empirical observation
	const thresh1 = 87.0 / 255.0 + 1e-10
	const thresh2 = 129.0 / 255.0 + 1e-10

	// Sort symbols by coverage (ascending), skip space
	// Find the 3 levels: 0 (space), light (smallest positive), dense (largest)
	var spaceChar rune = ' '
	var lightChar, denseChar rune
	var lightCov, denseCov float64 = 2.0, -1.0

	for _, sym := range symbols {
		if sym.Coverage == 0 {
			spaceChar = sym.Char
			continue
		}
		if sym.Coverage < lightCov {
			lightCov = sym.Coverage
			lightChar = sym.Char
		}
		if sym.Coverage > denseCov {
			denseCov = sym.Coverage
			denseChar = sym.Char
		}
	}

	if lightChar == 0 {
		return spaceChar
	}
	if denseChar == 0 || denseCov == lightCov {
		// Only 2 levels
		if brightness >= thresh1 {
			return lightChar
		}
		return spaceChar
	}

	if brightness >= thresh2 {
		return denseChar
	}
	if brightness >= thresh1 {
		return lightChar
	}
	return spaceChar
}"""

