import math

def calculateOutputSize(imgW, imgH, maxW, maxH, fontRatio=0.5):
    if maxW <= 0:
        maxW = 10000
    if maxH <= 0:
        maxH = 10000

    naturalH = maxW * imgH / imgW * fontRatio
    if naturalH <= maxH:
        h = max(1, math.ceil(naturalH))
        return (maxW, h)

    naturalW = maxH * imgW / imgH / fontRatio
    w = max(1, math.ceil(naturalW))
    w = min(w, maxW)
    return (w, maxH)

def calcSize(imgW, imgH, specMaxW, specMaxH, fontRatio=0.5):
    # Apply pixel limit: can't have more chars than pixels
    maxW = min(specMaxW, imgW)
    maxH_pixels = max(1, math.ceil(imgH / fontRatio))
    maxH = min(specMaxH, maxH_pixels)
    return calculateOutputSize(imgW, imgH, maxW, maxH, fontRatio)

# Test
for iw, ih in [(1,1), (2,2), (4,4), (8,8), (16,16), (100,100)]:
    w, h = calcSize(iw, ih, 100, 100)
    print(f"{iw}x{ih} -> {w}x{h}")
