package main

import (
	"encoding/binary"
	"fmt"
	"image"
	"image/color"
	"io"
	"bytes"
	"compress/lzw"
	"math"
)

// Simple TIFF decoder for basic uncompressed and LZW RGB/RGBA images
func decodeTIFF(data []byte) (*image.RGBA, error) {
	if len(data) < 8 {
		return nil, fmt.Errorf("TIFF: too short")
	}

	// Determine byte order
	var bo binary.ByteOrder
	if data[0] == 0x49 && data[1] == 0x49 {
		bo = binary.LittleEndian
	} else if data[0] == 0x4D && data[1] == 0x4D {
		bo = binary.BigEndian
	} else {
		return nil, fmt.Errorf("TIFF: invalid byte order")
	}

	magic := bo.Uint16(data[2:4])
	if magic != 42 {
		return nil, fmt.Errorf("TIFF: invalid magic %d", magic)
	}

	ifdOffset := int(bo.Uint32(data[4:8]))

	// Parse IFD
	tags := make(map[uint16]interface{})
	if err := parseTIFFTags(data, ifdOffset, bo, tags); err != nil {
		return nil, err
	}

	// Extract key values
	width := getTagInt(tags, 256, 0)
	height := getTagInt(tags, 257, 0)
	bitsPerSample := getTagInts(tags, 258)
	compression := getTagInt(tags, 259, 1)
	photometric := getTagInt(tags, 262, 2)
	samplesPerPixel := getTagInt(tags, 277, 3)
	stripOffsets := getTagInts(tags, 273)
	stripByteCounts := getTagInts(tags, 279)
	_ = photometric

	if width == 0 || height == 0 {
		return nil, fmt.Errorf("TIFF: invalid dimensions %dx%d", width, height)
	}

	bps := 8
	if len(bitsPerSample) > 0 {
		bps = bitsPerSample[0]
	}
	_ = bps

	img := image.NewRGBA(image.Rect(0, 0, width, height))

	// Read strip data
	var stripData []byte
	for i, offset := range stripOffsets {
		var byteCount int
		if i < len(stripByteCounts) {
			byteCount = stripByteCounts[i]
		} else {
			byteCount = len(data) - offset
		}
		if offset+byteCount > len(data) {
			byteCount = len(data) - offset
		}
		strip := data[offset : offset+byteCount]

		switch compression {
		case 1: // No compression
			stripData = append(stripData, strip...)
		case 5: // LZW
			reader := lzw.NewReader(bytes.NewReader(strip), lzw.MSB, 8)
			decoded, err := io.ReadAll(reader)
			reader.Close()
			if err != nil && len(decoded) == 0 {
				return nil, fmt.Errorf("TIFF: LZW decode error: %v", err)
			}
			stripData = append(stripData, decoded...)
		default:
			return nil, fmt.Errorf("TIFF: unsupported compression %d", compression)
		}
	}

	// Decode pixel data
	stride := samplesPerPixel
	if stride < 3 {
		stride = 3
	}
	pixIdx := 0
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			base := pixIdx * stride
			if base+2 >= len(stripData) {
				img.SetRGBA(x, y, color.RGBA{0, 0, 0, 255})
				continue
			}
			r := stripData[base]
			g := stripData[base+1]
			b := stripData[base+2]
			a := uint8(255)
			if samplesPerPixel >= 4 && base+3 < len(stripData) {
				a = stripData[base+3]
			}
			img.SetRGBA(x, y, color.RGBA{r, g, b, a})
			pixIdx++
		}
	}

	return img, nil
}

func parseTIFFTags(data []byte, ifdOffset int, bo binary.ByteOrder, tags map[uint16]interface{}) error {
	if ifdOffset+2 > len(data) {
		return fmt.Errorf("TIFF: IFD out of bounds")
	}

	nEntries := int(bo.Uint16(data[ifdOffset : ifdOffset+2]))
	pos := ifdOffset + 2

	for i := 0; i < nEntries; i++ {
		if pos+12 > len(data) {
			break
		}
		tag := bo.Uint16(data[pos : pos+2])
		fieldType := bo.Uint16(data[pos+2 : pos+4])
		count := int(bo.Uint32(data[pos+4 : pos+8]))
		valueOffset := data[pos+8 : pos+12]
		pos += 12

		var values []int
		typeSize := tiffTypeSize(fieldType)
		totalSize := count * typeSize

		var rawData []byte
		if totalSize <= 4 {
			rawData = valueOffset
		} else {
			offset := int(bo.Uint32(valueOffset))
			if offset+totalSize <= len(data) {
				rawData = data[offset : offset+totalSize]
			}
		}

		for j := 0; j < count && j*typeSize+typeSize <= len(rawData); j++ {
			offset := j * typeSize
			var val int
			switch fieldType {
			case 1: // BYTE
				val = int(rawData[offset])
			case 3: // SHORT
				if offset+2 <= len(rawData) {
					val = int(bo.Uint16(rawData[offset : offset+2]))
				}
			case 4: // LONG
				if offset+4 <= len(rawData) {
					val = int(bo.Uint32(rawData[offset : offset+4]))
				}
			case 5: // RATIONAL (2 longs)
				if offset+8 <= len(rawData) {
					num := int(bo.Uint32(rawData[offset : offset+4]))
					den := int(bo.Uint32(rawData[offset+4 : offset+8]))
					if den != 0 {
						val = int(math.Round(float64(num) / float64(den)))
					}
				}
			}
			values = append(values, val)
		}

		if len(values) == 1 {
			tags[tag] = values[0]
		} else if len(values) > 1 {
			tags[tag] = values
		}
	}

	return nil
}

func tiffTypeSize(t uint16) int {
	switch t {
	case 1: return 1 // BYTE
	case 2: return 1 // ASCII
	case 3: return 2 // SHORT
	case 4: return 4 // LONG
	case 5: return 8 // RATIONAL
	default: return 1
	}
}

func getTagInt(tags map[uint16]interface{}, tag uint16, def int) int {
	v, ok := tags[tag]
	if !ok {
		return def
	}
	switch val := v.(type) {
	case int:
		return val
	case []int:
		if len(val) > 0 {
			return val[0]
		}
	}
	return def
}

func getTagInts(tags map[uint16]interface{}, tag uint16) []int {
	v, ok := tags[tag]
	if !ok {
		return nil
	}
	switch val := v.(type) {
	case int:
		return []int{val}
	case []int:
		return val
	}
	return nil
}
