package main

/*
#include <stdlib.h>

// Declare the WebP function signatures
typedef unsigned char uint8_t;
uint8_t* WebPDecodeRGBA(const uint8_t* data, size_t data_size, int* width, int* height);
void WebPFree(void* ptr);
*/
import "C"
import (
	"fmt"
	"image"
	"image/color"
	"unsafe"
)

func decodeWebPWithCGO(data []byte) (*image.RGBA, error) {
	if len(data) == 0 {
		return nil, fmt.Errorf("empty data")
	}

	var width, height C.int
	ptr := C.WebPDecodeRGBA(
		(*C.uint8_t)(unsafe.Pointer(&data[0])),
		C.size_t(len(data)),
		&width,
		&height,
	)
	if ptr == nil {
		return nil, fmt.Errorf("WebP decode failed")
	}
	defer C.WebPFree(unsafe.Pointer(ptr))

	w := int(width)
	h := int(height)
	img := image.NewRGBA(image.Rect(0, 0, w, h))

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			idx := (y*w + x) * 4
			r := uint8(*((*C.uint8_t)(unsafe.Pointer(uintptr(unsafe.Pointer(ptr)) + uintptr(idx)))))
			g := uint8(*((*C.uint8_t)(unsafe.Pointer(uintptr(unsafe.Pointer(ptr)) + uintptr(idx+1)))))
			b := uint8(*((*C.uint8_t)(unsafe.Pointer(uintptr(unsafe.Pointer(ptr)) + uintptr(idx+2)))))
			a := uint8(*((*C.uint8_t)(unsafe.Pointer(uintptr(unsafe.Pointer(ptr)) + uintptr(idx+3)))))
			img.SetRGBA(x, y, color.RGBA{r, g, b, a})
		}
	}

	return img, nil
}
