package main

/*
#include <stdlib.h>
#cgo LDFLAGS: -lwebp

typedef unsigned char uint8_t;
uint8_t* WebPDecodeRGBA(const uint8_t* data, size_t data_size, int* width, int* height);
void WebPFree(void* ptr);
*/
import "C"
import (
	"fmt"
	"image"
	"image/color"
	"unsafe"
)

func decodeWebPWithCGO(data []byte) (*image.RGBA, error) {
	if len(data) == 0 {
		return nil, fmt.Errorf("empty data")
	}

	var width, height C.int
	ptr := C.WebPDecodeRGBA(
		(*C.uint8_t)(unsafe.Pointer(&data[0])),
		C.size_t(len(data)),
		&width,
		&height,
	)
	if ptr == nil {
		return nil, fmt.Errorf("WebP decode failed")
	}
	defer C.WebPFree(unsafe.Pointer(ptr))

	w := int(width)
	h := int(height)
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	pixelData := (*[1 << 30]byte)(unsafe.Pointer(ptr))[:w*h*4 : w*h*4]

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			idx := (y*w + x) * 4
			img.SetRGBA(x, y, color.RGBA{
				R: pixelData[idx],
				G: pixelData[idx+1],
				B: pixelData[idx+2],
				A: pixelData[idx+3],
			})
		}
	}

	return img, nil
}

// loadWebP uses CGO to decode WebP images
func loadWebP(data []byte) (*LoadedImage, error) {
	img, err := decodeWebPWithCGO(data)
	if err != nil {
		return nil, fmt.Errorf("WebP: %v", err)
	}
	bounds := img.Bounds()
	return &LoadedImage{
		Frames:  []ImageFrame{{Img: img, DelayMs: 0}},
		Width:   bounds.Dx(),
		Height:  bounds.Dy(),
		IsAnim:  false,
	}, nil
